"use client";

import { useEffect, useState } from "react";
import { createPortal } from "react-dom";

interface PortalProps {
    children: React.ReactNode;
}

export function Portal({ children }: PortalProps) {
    const [mounted, setMounted] = useState(false);

    useEffect(() => {
        setMounted(true);
        return () => setMounted(false);
    }, []);

    return mounted ? createPortal(children, document.body) : null;
}

import { useState, useRef, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Send, Bot, User, Database, Cpu, Activity, ShieldCheck, Sparkles, Loader2, Trash2, ChevronRight, MessageSquare, History, Plus, X, Paperclip, XCircle, FileText } from "lucide-react";
import { sendChatMessage, generateSoapNote } from "@/lib/api";
import ReactMarkdown from "react-markdown";

interface Message {
  role: "user" | "assistant";
  content: string;
  image?: string; // Optional base64 image
}

interface ChatSession {
  id: string;
  title: string;
  messages: Message[];
  updatedAt: number;
}

const SUGGESTED_QUERIES = [
  "What does a CTR > 0.5 indicate?",
  "Summarize the findings for Severe Cardiomegaly.",
  "How does the NIH dataset handle patient anonymity?",
  "What is the Radiographic Severity Index (RSI)?",
];

const INITIAL_MESSAGE: Message = {
  role: "assistant",
  content: "Hello Dr. Krtika Soni. I am Wavelength's Global AI Assistant powered by LLaMA-3. I have full access to our local NIH curated dataset containing 112,000+ patient records, as well as the active DenseNet classification models. How can I assist your clinical workflow today?"
};

export function AiChat() {
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [activeSessionId, setActiveSessionId] = useState<string | null>(null);
  const [input, setInput] = useState("");
  const [attachment, setAttachment] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isExporting, setIsExporting] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Load sessions from localStorage on mount
  useEffect(() => {
    const saved = localStorage.getItem("wavelength_chat_sessions");
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setSessions(parsed);
        if (parsed.length > 0) {
          setActiveSessionId(parsed[0].id);
        } else {
          createNewSession();
        }
      } catch (e) {
        console.error("Failed to parse chat sessions", e);
        createNewSession();
      }
    } else {
      createNewSession();
    }
  }, []);

  // Save sessions to localStorage whenever they change
  useEffect(() => {
    if (sessions.length > 0) {
      localStorage.setItem("wavelength_chat_sessions", JSON.stringify(sessions));
    }
  }, [sessions]);

  const activeSession = sessions.find(s => s.id === activeSessionId);
  const messages = activeSession?.messages || [];

  const createNewSession = () => {
    const newSession: ChatSession = {
      id: Date.now().toString(),
      title: "New Clinical Query",
      messages: [INITIAL_MESSAGE],
      updatedAt: Date.now()
    };
    setSessions(prev => [newSession, ...prev]);
    setActiveSessionId(newSession.id);
    setIsSidebarOpen(false);
  };

  const deleteSession = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setSessions(prev => {
      const filtered = prev.filter(s => s.id !== id);
      if (filtered.length === 0) {
        return [{
          id: Date.now().toString(),
          title: "New Clinical Query",
          messages: [INITIAL_MESSAGE],
          updatedAt: Date.now()
        }];
      }
      if (activeSessionId === id) {
        setActiveSessionId(filtered[0].id);
      }
      return filtered;
    });
  };

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  // Auto-resize textarea
  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 200)}px`;
    }
  }, [input]);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      if (event.target?.result) {
        setAttachment(event.target.result as string);
      }
    };
    reader.readAsDataURL(file);
    // Reset input so the same file could be uploaded again if needed
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const handleSend = async (overrideInput?: string) => {
    const textToSend = overrideInput || input;
    if ((!textToSend.trim() && !attachment) || isLoading || !activeSessionId) return;

    const currentAttachment = attachment; // capture current state
    const userMsg: Message = { role: "user", content: textToSend || "Uploaded an image for analysis.", image: currentAttachment || undefined };

    let newTitle = activeSession?.title;
    if (messages.length === 1) {
      newTitle = textToSend.slice(0, 30) + (textToSend.length > 30 ? "..." : (textToSend ? "" : "Image Analysis"));
    }

    setSessions(prev => prev.map(s => {
      if (s.id === activeSessionId) {
        return {
          ...s,
          title: newTitle || s.title,
          messages: [...s.messages, userMsg],
          updatedAt: Date.now()
        };
      }
      return s;
    }).sort((a, b) => b.updatedAt - a.updatedAt));

    if (!overrideInput) setInput("");
    setAttachment(null);
    setIsLoading(true);

    try {
      const history = messages.map(m => ({ role: m.role, content: m.content }));

      // If we have an image, we send the base64 string to the backend
      // But only the raw base64 data without the data:image/png;base64, prefix if desired. 
      // Our API handles it correctly since it's just passing it into prompt context currently.
      const response = await sendChatMessage(userMsg.content, history, currentAttachment || undefined);

      setSessions(prev => prev.map(s => {
        if (s.id === activeSessionId) {
          return {
            ...s,
            messages: [...s.messages, { role: "assistant", content: response.reply }],
            updatedAt: Date.now()
          };
        }
        return s;
      }));
    } catch {
      setSessions(prev => prev.map(s => {
        if (s.id === activeSessionId) {
          return {
            ...s,
            messages: [...s.messages, {
              role: "assistant",
              content: "I'm currently unable to connect to the LLM backend. Please check if the Ollama service is running."
            }],
            updatedAt: Date.now()
          };
        }
        return s;
      }));
    } finally {
      setIsLoading(false);
    }
  };

  const handleExportSoap = async () => {
    if (messages.length <= 1) return; // Only initial message

    setIsExporting(true);
    try {
      const history = messages.map(m => ({ role: m.role, content: m.content }));
      const response = await generateSoapNote(history);

      // Create a downloadable text file
      const blob = new Blob([response.soap], { type: "text/plain;charset=utf-8" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `clinical_soap_note_${new Date().toISOString().split('T')[0]}.txt`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    } catch (e) {
      console.error("Failed to export SOAP note", e);
      alert("Failed to synthesize SOAP note.");
    } finally {
      setIsExporting(false);
    }
  };

  const clearChat = () => {
    if (!activeSessionId) return;
    setSessions(prev => prev.map(s => {
      if (s.id === activeSessionId) {
        return {
          ...s,
          title: "New Clinical Query",
          messages: [INITIAL_MESSAGE],
          updatedAt: Date.now()
        };
      }
      return s;
    }));
    setInput("");
    setAttachment(null);
  };

  return (
    <div className="flex h-[calc(100vh-140px)] w-full rounded-3xl border border-slate-200 bg-white shadow-sm overflow-hidden relative">
      <div className="absolute top-0 right-0 p-8 opacity-5 pointer-events-none z-0">
        <Sparkles className="w-64 h-64 text-indigo-900" />
      </div>

      {/* History Sidebar */}
      <AnimatePresence>
        {(isSidebarOpen || window.innerWidth > 1024) && (
          <motion.div
            initial={{ width: 0, opacity: 0 }}
            animate={{ width: 320, opacity: 1 }}
            exit={{ width: 0, opacity: 0 }}
            className="h-full border-r border-slate-200 bg-slate-50 flex flex-col shrink-0 overflow-hidden relative z-20 absolute lg:relative hidden lg:flex shadow-xl lg:shadow-none"
          >
            <div className="p-4 border-b border-slate-200 flex items-center justify-between bg-white shrink-0">
              <div className="flex items-center gap-2 text-indigo-900 font-bold">
                <History className="w-5 h-5" />
                Chat History
              </div>
              <button
                onClick={() => setIsSidebarOpen(false)}
                className="lg:hidden p-2 text-slate-400 hover:text-slate-600 rounded-md hover:bg-slate-100"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="p-4 shrink-0">
              <button
                onClick={createNewSession}
                className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl shadow-md flex items-center justify-center gap-2 font-bold text-sm transition-all active:scale-95"
              >
                <Plus className="w-5 h-5" />
                New Consultation
              </button>
            </div>

            <div className="flex-1 overflow-y-auto px-4 pb-4 space-y-2 custom-scrollbar">
              {sessions.map(session => (
                <button
                  key={session.id}
                  onClick={() => { setActiveSessionId(session.id); setIsSidebarOpen(false); }}
                  className={`w-full text-left p-4 rounded-xl transition-all border group relative ${activeSessionId === session.id
                    ? "bg-white border-indigo-200 shadow-sm"
                    : "bg-transparent border-transparent hover:bg-slate-200/50"
                    }`}
                >
                  <div className={`text-sm font-bold truncate pr-6 ${activeSessionId === session.id ? 'text-indigo-900' : 'text-slate-700'}`}>
                    {session.title}
                  </div>
                  <div className="text-[10px] text-slate-500 font-medium mt-1">
                    {new Date(session.updatedAt).toLocaleDateString()} ΓÇó {session.messages.length - 1} msgs
                  </div>

                  {sessions.length > 1 && (
                    <button
                      onClick={(e) => deleteSession(e, session.id)}
                      className={`absolute right-3 top-1/2 -translate-y-1/2 p-1.5 rounded-md text-slate-400 hover:text-rose-600 hover:bg-rose-50 transition-colors opacity-0 group-hover:opacity-100 ${activeSessionId === session.id ? 'opacity-100' : ''}`}
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  )}
                </button>
              ))}
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {/* Mobile Overlay */}
        {isSidebarOpen && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={() => setIsSidebarOpen(false)}
            className="absolute inset-0 bg-slate-900/20 backdrop-blur-sm z-10 lg:hidden"
          />
        )}

        {/* Mobile Sidebar (Absolute positioned) */}
        {isSidebarOpen && (
          <motion.div
            initial={{ x: "-100%" }}
            animate={{ x: 0 }}
            exit={{ x: "-100%" }}
            transition={{ type: "spring", bounce: 0, duration: 0.4 }}
            className="absolute top-0 left-0 bottom-0 w-80 border-r border-slate-200 bg-slate-50 flex flex-col shrink-0 overflow-hidden z-20 shadow-2xl lg:hidden"
          >
            <div className="p-4 border-b border-slate-200 flex items-center justify-between bg-white shrink-0">
              <div className="flex items-center gap-2 text-indigo-900 font-bold">
                <History className="w-5 h-5" />
                Chat History
              </div>
              <button
                onClick={() => setIsSidebarOpen(false)}
                className="p-2 text-slate-400 hover:text-slate-600 rounded-md hover:bg-slate-100"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="p-4 shrink-0">
              <button
                onClick={createNewSession}
                className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl shadow-md flex items-center justify-center gap-2 font-bold text-sm transition-all active:scale-95"
              >
                <Plus className="w-5 h-5" />
                New Consultation
              </button>
            </div>

            <div className="flex-1 overflow-y-auto px-4 pb-4 space-y-2 custom-scrollbar">
              {sessions.map(session => (
                <button
                  key={session.id}
                  onClick={() => { setActiveSessionId(session.id); setIsSidebarOpen(false); }}
                  className={`w-full text-left p-4 rounded-xl transition-all border group relative ${activeSessionId === session.id
                    ? "bg-white border-indigo-200 shadow-sm"
                    : "bg-transparent border-transparent hover:bg-slate-200/50"
                    }`}
                >
                  <div className={`text-sm font-bold truncate pr-6 ${activeSessionId === session.id ? 'text-indigo-900' : 'text-slate-700'}`}>
                    {session.title}
                  </div>
                  <div className="text-[10px] text-slate-500 font-medium mt-1">
                    {new Date(session.updatedAt).toLocaleDateString()} ΓÇó {session.messages.length - 1} msgs
                  </div>

                  {sessions.length > 1 && (
                    <button
                      onClick={(e) => deleteSession(e, session.id)}
                      className={`absolute right-3 top-1/2 -translate-y-1/2 p-1.5 rounded-md text-slate-400 hover:text-rose-600 hover:bg-rose-50 transition-colors opacity-0 group-hover:opacity-100 ${activeSessionId === session.id ? 'opacity-100' : ''}`}
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  )}
                </button>
              ))}
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <div className="flex-1 flex flex-col min-w-0 relative z-10">
        {/* Header */}
        <div className="px-6 sm:px-8 py-5 border-b border-slate-100 flex items-center justify-between bg-white/95 backdrop-blur-sm relative z-10 transition-all">
          <div className="flex items-center gap-4">
            <button
              onClick={() => setIsSidebarOpen(true)}
              className="lg:hidden p-2 -ml-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-xl transition-colors"
              title="View History"
            >
              <History className="w-6 h-6" />
            </button>
            <div className="hidden sm:flex w-12 h-12 rounded-2xl bg-gradient-to-br from-indigo-600 to-purple-600 items-center justify-center shadow-lg shadow-indigo-500/20 relative shrink-0">
              <Bot className="w-6 h-6 text-white" />
              <div className="absolute -bottom-1 -right-1 w-4 h-4 rounded-full bg-emerald-500 border-2 border-white" />
            </div>
            <div>
              <h2 className="text-xl font-extrabold text-slate-900 tracking-tight flex items-center gap-2">
                Global Clinical Assistant
              </h2>
              <div className="flex flex-wrap items-center gap-2 sm:gap-3 text-[10px] sm:text-xs font-bold uppercase tracking-wider text-slate-500 mt-1">
                <span className="flex items-center gap-1 bg-slate-50 px-2 py-0.5 rounded border border-slate-100"><Cpu className="w-3 h-3 text-indigo-500" /> LLaMA-3 8B</span>
                <span className="flex items-center gap-1 bg-slate-50 px-2 py-0.5 rounded border border-slate-100 hidden sm:flex"><Database className="w-3 h-3 text-emerald-500" /> NIH Curated Data</span>
                <span className="flex items-center gap-1 bg-slate-50 px-2 py-0.5 rounded border border-slate-100 hidden md:flex"><ShieldCheck className="w-3 h-3 text-blue-500" /> HIPAA Secure</span>
              </div>
            </div>
          </div>
          <div className="flex items-center gap-2 sm:gap-3">
            <button
              onClick={handleExportSoap}
              disabled={isExporting || messages.length <= 1}
              className="p-2 sm:px-4 sm:py-2 rounded-xl text-sm font-bold transition-all flex items-center gap-2 bg-indigo-50 border border-indigo-100 text-indigo-600 hover:bg-indigo-600 hover:text-white shadow-sm disabled:opacity-50 disabled:cursor-not-allowed"
              title="Export Conversation as SOAP Note"
            >
              {isExporting ? <Loader2 className="w-4 h-4 animate-spin" /> : <FileText className="w-4 h-4" />}
              <span className="hidden xl:inline">Export SOAP</span>
            </button>
            <button
              onClick={clearChat}
              className="p-2 sm:px-4 sm:py-2 rounded-xl text-sm font-bold transition-all flex items-center gap-2 bg-white border border-slate-200 text-slate-500 hover:text-rose-600 hover:bg-rose-50 hover:border-rose-200 shadow-sm"
              title="Clear Current Chat"
            >
              <Trash2 className="w-4 h-4" />
              <span className="hidden xl:inline">Clear Chat</span>
            </button>
            <div className="hidden lg:flex items-center gap-2 px-3 py-1.5 bg-emerald-50 border border-emerald-100 rounded-full">
              <Activity className="w-4 h-4 text-emerald-500 animate-pulse" />
              <span className="text-[10px] font-bold text-emerald-700 uppercase tracking-widest hidden xl:inline">Active Runtime</span>
            </div>
          </div>
        </div>

        {/* Chat Area */}
        <div className="flex-1 overflow-y-auto p-4 sm:p-8 space-y-6 bg-slate-50/50 relative z-10 custom-scrollbar">
          {messages.map((msg, idx) => (
            <motion.div
              key={idx}
              initial={{ opacity: 0, y: 10, scale: 0.98 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              transition={{ duration: 0.3 }}
              className={`flex w-full ${msg.role === "user" ? "justify-end" : "justify-start"}`}
            >
              <div className={`flex gap-3 sm:gap-4 max-w-[95%] sm:max-w-[85%] lg:max-w-[75%] ${msg.role === "user" ? "flex-row-reverse" : "flex-row"}`}>
                {/* Avatar */}
                <div className="shrink-0 mt-1">
                  {msg.role === "assistant" ? (
                    <div className="w-8 h-8 sm:w-10 sm:h-10 rounded-xl bg-gradient-to-br from-indigo-500 to-purple-600 flex items-center justify-center shadow-md">
                      <Bot className="w-5 h-5 text-white" />
                    </div>
                  ) : (
                    <div className="w-8 h-8 sm:w-10 sm:h-10 rounded-xl bg-slate-200 flex items-center justify-center border border-slate-300">
                      <User className="w-5 h-5 text-slate-600" />
                    </div>
                  )}
                </div>

                {/* Message Bubble */}
                <div className={`
                    p-4 sm:p-5 rounded-2xl text-sm sm:text-base leading-relaxed shadow-sm flex flex-col gap-3
                    ${msg.role === "user"
                    ? "bg-indigo-900 text-white rounded-tr-none"
                    : "bg-white border border-slate-200 text-slate-800 rounded-tl-none"}
                  `}>
                  {msg.image && (
                    <div className="w-48 sm:w-64 aspect-square rounded-xl overflow-hidden bg-slate-950 border border-slate-700/50 shadow-inner">
                      <img src={msg.image} alt="User attached medical image" className="w-full h-full object-cover" />
                    </div>
                  )}

                  {msg.role === "assistant" ? (
                    <div className="prose prose-sm sm:prose-base max-w-none prose-p:mb-3 last:prose-p:mb-0 prose-p:leading-relaxed prose-strong:text-indigo-900 prose-strong:font-bold prose-ul:my-2 prose-li:my-0 prose-a:text-indigo-600 prose-a:no-underline hover:prose-a:underline text-slate-800">
                      <ReactMarkdown>{msg.content}</ReactMarkdown>
                    </div>
                  ) : (
                    <div className="whitespace-pre-wrap font-medium">{msg.content}</div>
                  )}
                </div>
              </div>
            </motion.div>
          ))}

          {/* Suggested Queries - Only show if conversation just started */}
          {messages.length === 1 && (
            <motion.div
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.2 }}
              className="flex flex-col gap-3 mt-8 ml-2 sm:ml-14 max-w-full sm:max-w-[80%]"
            >
              <div className="flex items-center gap-2 text-slate-400 mb-1">
                <MessageSquare className="w-4 h-4" />
                <span className="text-xs font-bold uppercase tracking-widest">Suggested Clinical Queries</span>
              </div>
              <div className="flex flex-wrap gap-2">
                {SUGGESTED_QUERIES.map((query, index) => (
                  <button
                    key={index}
                    onClick={() => handleSend(query)}
                    className="px-4 py-2 bg-white border border-slate-200 rounded-xl text-sm text-slate-600 font-medium hover:border-indigo-300 hover:text-indigo-700 hover:bg-indigo-50 transition-all text-left shadow-sm flex items-center justify-between gap-2 group w-full sm:w-auto"
                  >
                    {query}
                    <ChevronRight className="w-4 h-4 text-slate-300 group-hover:text-indigo-400 transition-colors shrink-0" />
                  </button>
                ))}
              </div>
            </motion.div>
          )}

          {isLoading && (
            <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="flex justify-start">
              <div className="flex gap-4 max-w-[80%]">
                <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-indigo-500 to-purple-600 flex items-center justify-center shadow-md shrink-0 mt-1">
                  <Bot className="w-5 h-5 text-white" />
                </div>
                <div className="p-5 rounded-2xl rounded-tl-none bg-white border border-slate-200 shadow-sm flex items-center gap-4">
                  <div className="flex gap-1.5">
                    <motion.div animate={{ y: [0, -5, 0] }} transition={{ duration: 0.6, repeat: Infinity, delay: 0 }} className="w-2 h-2 bg-indigo-500 rounded-full" />
                    <motion.div animate={{ y: [0, -5, 0] }} transition={{ duration: 0.6, repeat: Infinity, delay: 0.2 }} className="w-2 h-2 bg-indigo-400 rounded-full" />
                    <motion.div animate={{ y: [0, -5, 0] }} transition={{ duration: 0.6, repeat: Infinity, delay: 0.4 }} className="w-2 h-2 bg-indigo-300 rounded-full" />
                  </div>
                  <span className="text-sm font-bold text-indigo-600 uppercase tracking-widest">Synthesizing clinical response...</span>
                </div>
              </div>
            </motion.div>
          )}
          <div ref={messagesEndRef} className="h-4" />
        </div>

        {/* Input Area */}
        <div className="p-4 sm:p-6 bg-white border-t border-slate-100 relative z-10 transition-all flex flex-col">

          {/* Image Attachment Preview */}
          <AnimatePresence>
            {attachment && (
              <motion.div
                initial={{ opacity: 0, height: 0, marginBottom: 0 }}
                animate={{ opacity: 1, height: 'auto', marginBottom: 12 }}
                exit={{ opacity: 0, height: 0, marginBottom: 0 }}
                className="flex items-center gap-4 bg-slate-50 border border-slate-200 p-3 rounded-2xl w-fit"
              >
                <div className="w-16 h-16 rounded-xl bg-slate-900 overflow-hidden relative border border-slate-300 shadow-sm">
                  <img src={attachment} alt="Attachment Preview" className="w-full h-full object-cover" />
                </div>
                <div className="flex flex-col">
                  <span className="text-sm font-bold text-slate-800">Medical Image Attached</span>
                  <span className="text-xs text-slate-500 font-medium">Ready for multimodal synthesis</span>
                </div>
                <button
                  onClick={() => setAttachment(null)}
                  className="p-1 ml-4 text-slate-400 hover:text-rose-500 transition-colors"
                >
                  <XCircle className="w-6 h-6" />
                </button>
              </motion.div>
            )}
          </AnimatePresence>

          <form
            onSubmit={(e) => { e.preventDefault(); handleSend(); }}
            className="relative flex items-end gap-3 max-w-5xl mx-auto w-full"
          >
            <div className="relative flex-1 bg-slate-50 border border-slate-300 rounded-2xl overflow-hidden focus-within:ring-4 focus-within:ring-indigo-500/20 focus-within:border-indigo-500 transition-all shadow-sm flex">
              <input
                type="file"
                accept="image/png, image/jpeg, image/jpg"
                className="hidden"
                ref={fileInputRef}
                onChange={handleImageUpload}
              />
              <button
                type="button"
                onClick={() => fileInputRef.current?.click()}
                className="p-4 text-slate-400 hover:text-indigo-600 transition-colors self-end mb-1"
                title="Attach Medical Image"
              >
                <Paperclip className="w-5 h-5" />
              </button>
              <textarea
                ref={textareaRef}
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' && !e.shiftKey) {
                    e.preventDefault();
                    handleSend();
                  }
                }}
                placeholder="Ask about patient records or dataset statistics..."
                className="w-full bg-transparent py-4 pr-4 pl-0 outline-none resize-none min-h-[60px] max-h-[200px] text-sm sm:text-base text-slate-800 placeholder:text-slate-400 font-medium custom-scrollbar"
                rows={1}
              />
            </div>
            <button
              type="submit"
              disabled={(!input.trim() && !attachment) || isLoading}
              className="w-[60px] h-[60px] rounded-2xl bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-200 disabled:text-slate-400 text-white flex items-center justify-center transition-all shadow-md active:scale-95 shrink-0"
            >
              {isLoading ? <Loader2 className="w-6 h-6 animate-spin" /> : <Send className="w-6 h-6 ml-1" />}
            </button>
          </form>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { Layers, Sparkles, AlertTriangle, Loader2, Database, Image as ImageIcon, Info, Activity, ChevronRight, X, ShieldAlert, FileText } from "lucide-react";
import ReactMarkdown from "react-markdown";
import { getReports } from "@/lib/api";
import type { PredictionResponse, Report } from "@/types";
import { format } from "date-fns";
import { ExportReportButton } from "@/components/ui/export-report-button";
import { ImageViewer } from "@/components/viewer/image-viewer";
import { DiseaseTable } from "@/components/results/disease-table";
import { RiskBadge } from "@/components/results/risk-badge";
import { UncertaintyIndicator } from "@/components/results/uncertainty-indicator";
import { DiseaseTimeline } from "@/components/results/disease-timeline";
import { AmbientDictation } from "@/components/ui/ambient-dictation";

interface AiSummaryProps {
    initialResult?: PredictionResponse | null;
}

export function AiSummary({ initialResult }: AiSummaryProps) {
    const [reports, setReports] = useState<Report[]>([]);
    const [loading, setLoading] = useState(true);
    const [selectedReportId, setSelectedReportId] = useState<string | null>(initialResult?.report_id || null);

    const [guideline, setGuideline] = useState<string | null>(null);
    const [loadingGuideline, setLoadingGuideline] = useState(false);
    const [summaryMode, setSummaryMode] = useState<'clinical' | 'patient'>('clinical');

    const fetchReportsSilently = async () => {
        try {
            const data = await getReports();
            data.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
            setReports(data);
        } catch (err) {
            console.error("Polling error", err);
        }
    };

    useEffect(() => {
        const fetchAll = async () => {
            setLoading(true);
            await fetchReportsSilently();
            setLoading(false);
        };
        fetchAll();
    }, []);

    useEffect(() => {
        if (!selectedReportId && reports.length > 0) {
            setSelectedReportId(reports[0].report_id);
        }
    }, [reports, selectedReportId]);

    const selectedReport = reports.find(r => r.report_id === selectedReportId) || initialResult?.report;

    useEffect(() => {
        const isGenerating =
            selectedReport?.ai_summary?.includes("generating") ||
            selectedReport?.ai_second_opinion?.includes("Analyzing");

        if (isGenerating) {
            const interval = setInterval(() => {
                fetchReportsSilently();
            }, 2500);
            return () => clearInterval(interval);
        }
    }, [selectedReport]);

    useEffect(() => {
        if (!selectedReport) return;

        const topDisease = Object.keys(selectedReport.disease_probabilities || {}).reduce((a, b) =>
            (selectedReport.disease_probabilities[a] || 0) > (selectedReport.disease_probabilities[b] || 0) ? a : b
            , "No Finding");

        const fetchGuideline = async () => {
            setLoadingGuideline(true);
            try {
                const res = await fetch(`http://127.0.0.1:8000/api/analytics/guidelines?disease=${encodeURIComponent(topDisease)}`);
                if (res.ok) {
                    const data = await res.json();
                    setGuideline(data.guideline);
                }
            } catch (err) {
                console.error("Failed to fetch guideline:", err);
                setGuideline("Clinical correlation required. Further imaging may be indicated based on patient presentation.");
            } finally {
                setLoadingGuideline(false);
            }
        };

        fetchGuideline();
    }, [selectedReport]);

    if (loading && reports.length === 0) {
        return (
            <div className="flex flex-col items-center justify-center min-h-[600px] rounded-2xl border border-[#e2e8f0] bg-white shadow-sm overflow-hidden relative">
                <Loader2 className="w-8 h-8 text-indigo-600 animate-spin mb-4" />
                <p className="text-slate-500 font-medium">Synthesizing clinical histories...</p>
            </div>
        );
    }

    const topDisease = selectedReport ? Object.keys(selectedReport.disease_probabilities || {}).reduce((a, b) =>
        (selectedReport.disease_probabilities[a] || 0) > (selectedReport.disease_probabilities[b] || 0) ? a : b
        , "No Finding") : "No Finding";

    return (
        <div className="flex flex-col lg:flex-row min-h-[700px] gap-6">
            {/* Master: List of Summaries */}
            <div className="w-full lg:w-80 flex flex-col gap-4">
                <div className="bg-white rounded-2xl border border-slate-200 p-4 shadow-sm h-full max-h-[85vh] overflow-y-auto custom-scrollbar">
                    <div className="flex items-center gap-2 mb-4 px-2 sticky top-0 bg-white py-2 z-10 border-b border-slate-100">
                        <Layers className="w-5 h-5 text-indigo-600" />
                        <h3 className="font-bold text-slate-900 text-sm">Summary Collection</h3>
                    </div>
                    <div className="space-y-2 pr-1">
                        {reports.length === 0 && !initialResult ? (
                            <p className="text-xs text-slate-400 text-center py-8">No historical summaries found.</p>
                        ) : (
                            reports.map((report) => (
                                <button
                                    key={report.report_id}
                                    onClick={() => setSelectedReportId(report.report_id)}
                                    className={`w-full text-left p-4 rounded-xl transition-all border ${selectedReportId === report.report_id
                                        ? "bg-indigo-50 border-indigo-200 shadow-sm"
                                        : "bg-slate-50/50 hover:bg-slate-50 border-slate-200/50"
                                        }`}
                                >
                                    <div className="flex justify-between items-start mb-2">
                                        <span className={`text-[10px] font-bold ${selectedReportId === report.report_id ? 'text-indigo-600' : 'text-slate-500'} uppercase tracking-tight`}>
                                            Ref: {report.report_id.substring(0, 8)}
                                        </span>
                                        <span className="text-[10px] text-slate-400 font-medium">
                                            {format(new Date(report.timestamp), "MMM dd")}
                                        </span>
                                    </div>
                                    <div className="text-sm font-bold text-slate-800 truncate">
                                        {report.patient_details?.name || "Anonymous Patient"}
                                    </div>
                                    <div className="text-[10px] mt-1 text-slate-500 font-medium uppercase tracking-wider flex items-center justify-between">
                                        Risk: {report.risk_assessment?.risk_level || "UNKNOWN"}
                                    </div>
                                </button>
                            ))
                        )}
                    </div>
                </div>
            </div>

            {/* Detail: Summary Content */}
            <div className="flex-1 flex flex-col bg-white rounded-3xl border border-slate-200 shadow-sm relative overflow-hidden h-[85vh] overflow-y-auto custom-scrollbar">
                <div className="absolute inset-0 bg-grid-slate-100/[0.04] bg-[size:20px_20px] pointer-events-none" />
                <div className="absolute top-0 left-0 right-0 h-48 bg-gradient-to-b from-slate-50 to-transparent pointer-events-none" />

                <div className="relative z-10 p-8 flex-1 flex flex-col">
                    {selectedReport ? (
                        <>
                            <div className="flex flex-col sm:flex-row sm:items-center gap-4 mb-8">
                                <div className="w-16 h-16 rounded-2xl bg-gradient-to-br from-indigo-500 to-purple-600 flex items-center justify-center shadow-lg shadow-indigo-200 shrink-0">
                                    <Activity className="w-8 h-8 text-white" />
                                </div>
                                <div className="flex-1">
                                    <h2 className="text-2xl font-extrabold text-slate-900 tracking-tight">
                                        Patient AI Diagnostic Report
                                    </h2>
                                    <div className="flex items-center gap-2 mt-1">
                                        <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest bg-slate-100 px-2 py-0.5 rounded border border-slate-200">
                                            ID: {selectedReport.report_id}
                                        </span>
                                        <span className="text-[10px] font-bold text-indigo-600 uppercase tracking-widest bg-indigo-50 px-2 py-0.5 rounded border border-indigo-100">
                                            {selectedReport.patient_details?.name || "Anonymous Patient"}
                                        </span>
                                    </div>
                                </div>
                                <div className="shrink-0">
                                    <ExportReportButton
                                        patientName={selectedReport.patient_details?.name || "Anonymous Patient"}
                                        patientId={selectedReport.report_id || ""}
                                        date={selectedReport.timestamp || new Date().toISOString().split('T')[0]}
                                        findings={`${selectedReport.ai_summary || "No clinical summary provided."}\n\n${selectedReport.ai_second_opinion ? `--- SENIOR RADIOLOGIST SECOND OPINION ---\n${selectedReport.ai_second_opinion}` : ""}`.trim()}
                                        aiConfidence={Object.values(selectedReport.disease_probabilities || {}).length > 0 ? Math.max(...Object.values(selectedReport.disease_probabilities || {}) as number[]) * 100 : undefined}
                                        base64Images={selectedReport.images?.original ? [selectedReport.images.original] : []}
                                    />
                                </div>
                            </div>

                            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 mb-8">
                                {/* Left Column: Visuals */}
                                <div className="space-y-6">
                                    <ImageViewer
                                        preview={selectedReport.images?.original ? (selectedReport.images.original.startsWith('data:') ? selectedReport.images.original : `data:image/png;base64,${selectedReport.images.original}`) : null}
                                        segmentationOverlay={selectedReport.images?.segmentation_overlay ? (selectedReport.images.segmentation_overlay.startsWith('data:') ? selectedReport.images.segmentation_overlay : `data:image/png;base64,${selectedReport.images.segmentation_overlay}`) : null}
                                        heatmapOverlay={selectedReport.images?.heatmap ? (selectedReport.images.heatmap.startsWith('data:') ? selectedReport.images.heatmap : `data:image/png;base64,${selectedReport.images.heatmap}`) : null}
                                        topDisease={topDisease}
                                    />

                                    <div className="p-5 bg-slate-50 rounded-2xl border border-slate-200">
                                        <div className="flex items-center gap-2 mb-3 text-[#1f2937]">
                                            <Info className="w-4 h-4 text-indigo-500" />
                                            <h4 className="font-bold text-sm">Differential Diagnosis Summary</h4>
                                        </div>
                                        <p className="text-xs text-slate-600 leading-relaxed font-medium italic">
                                            "The primary radiological finding indicates a strong clinical correlation for <strong>{topDisease}</strong>. The neural network identified several focal points of architectural distortion. Please correlate these visual heatmaps with patient history and secondary symptoms."
                                        </p>
                                    </div>
                                </div>

                                {/* Right Column: Data & Analytics */}
                                <div className="space-y-6">
                                    {/* Clinical Next Step Guideline */}
                                    <div className="p-5 bg-indigo-50 border border-indigo-200 rounded-2xl shadow-sm relative overflow-hidden">
                                        <div className="flex items-start gap-3 relative z-10">
                                            <div className="p-2 bg-indigo-100 rounded-lg text-indigo-700 shrink-0">
                                                <Activity className="w-5 h-5" />
                                            </div>
                                            <div>
                                                <h4 className="font-bold text-indigo-900 text-sm mb-1 uppercase tracking-wider flex items-center gap-2">
                                                    Clinical Next Step
                                                    <span className="text-[9px] bg-indigo-200 text-indigo-800 px-1.5 py-0.5 rounded uppercase font-bold tracking-widest">
                                                        Guideline
                                                    </span>
                                                </h4>
                                                {loadingGuideline ? (
                                                    <div className="flex items-center gap-2 text-indigo-600/70 text-sm mt-1 animate-pulse font-medium">
                                                        <div className="w-4 h-4 border-2 border-indigo-600/50 border-t-transparent rounded-full animate-spin" />
                                                        Consulting medical guidelines...
                                                    </div>
                                                ) : (
                                                    <p className="text-sm text-indigo-800 font-medium leading-relaxed bg-white/50 p-3 rounded-lg border border-indigo-100 mt-2 shadow-sm">
                                                        {guideline || "Consult standard clinical guidelines for appropriate follow-up."}
                                                    </p>
                                                )}
                                            </div>
                                        </div>
                                    </div>

                                    <DiseaseTable
                                        probabilities={selectedReport.disease_probabilities || {}}
                                        uncertainty={selectedReport.uncertainty || {}}
                                        justifications={selectedReport.justifications || {}}
                                        differentialDiagnoses={selectedReport.differential_diagnoses || []}
                                    />

                                    {selectedReport.risk_assessment && (
                                        <RiskBadge
                                            riskAssessment={selectedReport.risk_assessment}
                                            inferenceTime={(selectedReport as any).inference_time_ms || 120}
                                            calibrated={selectedReport.calibrated || false}
                                        />
                                    )}

                                    {selectedReport.uncertainty && (
                                        <UncertaintyIndicator uncertainty={selectedReport.uncertainty} />
                                    )}
                                </div>
                            </div>

                            {/* Full Width Sections */}
                            <div className="space-y-8">
                                {/* AI Summary Section */}
                                <div className="p-8 bg-gradient-to-br from-indigo-50 to-white rounded-3xl border border-indigo-100 shadow-sm relative overflow-hidden">
                                    <div className="absolute top-0 right-0 p-6 opacity-10">
                                        <Sparkles className="w-32 h-32 text-indigo-600" />
                                    </div>
                                    <div className="relative z-10">
                                        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
                                            <div className="flex items-center gap-2 text-indigo-900">
                                                <Sparkles className="w-5 h-5" />
                                                <h4 className="font-extrabold text-lg">AI Report Synthesis</h4>
                                            </div>

                                            {/* Mode Toggle */}
                                            <div className="flex items-center bg-white rounded-lg p-1 border border-indigo-100 shadow-sm relative z-20 w-fit">
                                                <button
                                                    onClick={() => setSummaryMode('clinical')}
                                                    className={`px-4 py-1.5 text-xs font-bold rounded-md transition-colors ${summaryMode === 'clinical' ? 'bg-indigo-600 text-white shadow focus:outline-none' : 'text-slate-500 hover:text-slate-900'}`}
                                                >
                                                    Clinical View
                                                </button>
                                                <button
                                                    onClick={() => setSummaryMode('patient')}
                                                    className={`px-4 py-1.5 text-xs font-bold rounded-md transition-colors ${summaryMode === 'patient' ? 'bg-emerald-600 text-white shadow focus:outline-none' : 'text-slate-500 hover:text-slate-900'}`}
                                                >
                                                    Patient View
                                                </button>
                                            </div>
                                        </div>
                                        <div className="prose prose-slate max-w-none text-slate-700 leading-relaxed font-medium text-sm">
                                            <ReactMarkdown>
                                                {summaryMode === 'clinical'
                                                    ? (selectedReport.ai_summary || "Synthesizing clinical AI report in background...")
                                                    : ((selectedReport as any).ai_patient_summary || "Synthesizing patient-friendly report in background...")}
                                            </ReactMarkdown>
                                        </div>

                                        {summaryMode === 'clinical' && selectedReport.ai_second_opinion && (
                                            <>
                                                <hr className="my-6 border-indigo-100" />
                                                <h4 className="font-bold text-emerald-800 text-sm mb-3 uppercase tracking-wider flex items-center gap-2">
                                                    <ShieldAlert className="w-4 h-4" />
                                                    Comparative Senior Second Opinion
                                                </h4>
                                                <div className="prose prose-slate max-w-none text-slate-700 leading-relaxed text-sm bg-emerald-50/50 p-5 rounded-xl border border-emerald-100">
                                                    <ReactMarkdown>{selectedReport.ai_second_opinion}</ReactMarkdown>
                                                </div>
                                            </>
                                        )}
                                    </div>
                                </div>

                                {/* Longitudinal Timeline Section */}
                                <div className="p-8 bg-white rounded-3xl border border-slate-200 shadow-sm">
                                    <div className="flex items-center gap-2 mb-6 text-slate-900">
                                        <ChevronRight className="w-5 h-5 text-indigo-500" />
                                        <h4 className="font-extrabold text-lg">Longitudinal Case Tracking</h4>
                                    </div>
                                    <DiseaseTimeline topDisease={topDisease} />
                                </div>

                                {/* Similar Cases Section */}
                                {selectedReport.similar_cases && selectedReport.similar_cases.length > 0 && (
                                    <div className="bg-slate-50 border border-slate-200 rounded-3xl p-8">
                                        <div className="flex items-center gap-3 mb-6">
                                            <div className="p-2 bg-slate-200 rounded-xl">
                                                <Database className="w-6 h-6 text-slate-700" />
                                            </div>
                                            <div>
                                                <h4 className="font-extrabold text-lg text-slate-900">Visually Similar Cases</h4>
                                                <p className="text-xs font-bold text-slate-500 uppercase tracking-widest">Matched via Repository Core</p>
                                            </div>
                                        </div>
                                        <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                                            {selectedReport.similar_cases.map((sim: any, i: number) => (
                                                <div key={i} className="bg-white rounded-2xl border border-slate-200 overflow-hidden shadow-sm group hover:border-indigo-200 transition-all">
                                                    <div className="aspect-square bg-slate-900 relative">
                                                        <img src={sim.url} alt={sim.diagnosis} className="w-full h-full object-cover group-hover:scale-105 transition-transform" />
                                                        <div className="absolute top-2 right-2 bg-indigo-600 text-white text-[10px] font-bold px-2 py-0.5 rounded backdrop-blur-md">
                                                            {(sim.similarity * 100).toFixed(0)}% MATCH
                                                        </div>
                                                    </div>
                                                    <div className="p-3">
                                                        <h5 className="font-bold text-slate-900 text-xs mb-1 truncate">{sim.diagnosis}</h5>
                                                        <p className="text-[10px] text-slate-500 font-medium uppercase tracking-wider">{sim.gender}, {sim.age}y</p>
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                )}

                                {/* Ambient Dictation Integration */}
                                <div className="pt-2">
                                    <AmbientDictation onSaveNotes={(notes) => {
                                        console.log("Physician notes saved:", notes);
                                    }} />
                                </div>
                            </div>
                        </>
                    ) : (
                        <div className="flex flex-col items-center justify-center flex-1 text-center bg-slate-50 rounded-3xl border border-dashed border-slate-300">
                            <Layers className="w-16 h-16 text-slate-300 mb-4" />
                            <h3 className="text-xl font-bold text-slate-500">Select a report to view detailed AI synthesis</h3>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { ActivitySquare, Database, Cpu, Wifi, Server, Hexagon, Zap, ShieldCheck, Network, UploadCloud, DownloadCloud, Play } from "lucide-react";

export function DeveloperMode() {
    // Quantization State
    const [precision, setPrecision] = useState<'FP32' | 'INT8'>('FP32');
    const [qLogs, setQLogs] = useState<string[]>([
        "[SYSTEM] Wavelength Telemetry Engine v2.1.0 Initialized",
        "[INFO] Loaded DenseNet-121 in FP32 format.",
    ]);

    // Derived metrics based on precision
    const metrics = {
        vram: precision === 'FP32' ? "4.15 GB" : "1.24 GB",
        latency: precision === 'FP32' ? "142 ms" : "48 ms",
        throughput: precision === 'FP32' ? "24 req/s" : "85 req/s",
        size: precision === 'FP32' ? "28.5 MB" : "7.2 MB",
        temp: precision === 'FP32' ? "72 ┬░C" : "54 ┬░C",
    };

    const addLog = (msg: string) => {
        setQLogs((prev) => {
            const next = [...prev, `${new Date().toISOString().split('T')[1].split('.')[0]} ${msg}`];
            return next.slice(-15);
        });
    };

    const handleQuantize = (p: 'FP32' | 'INT8') => {
        if (p === precision) return;
        setPrecision(p);
        if (p === 'INT8') {
            addLog("[WARN] Initiating dynamic post-training quantization to INT8...");
            setTimeout(() => addLog("[INFO] Calibrating activations using representative dataset..."), 500);
            setTimeout(() => addLog("[INFO] Quantization complete. Memory footprint reduced by 4x."), 1500);
        } else {
            addLog("[INFO] Reloading FP32 precision weights...");
            setTimeout(() => addLog("[DEBUG] Allocated 4.15GB VRAM for full-precision model."), 500);
        }
    };

    // Federated Learning State
    const [flStatus, setFlStatus] = useState<'IDLE' | 'TRAINING' | 'AGGREGATING' | 'COMPLETE'>('IDLE');
    const [globalEpoch, setGlobalEpoch] = useState(12);
    const [nodes, setNodes] = useState([
        { id: "Node A (NY)", data: 1450, status: "Idle", progress: 0 },
        { id: "Node B (LN)", data: 820, status: "Idle", progress: 0 },
        { id: "Node C (TK)", data: 2100, status: "Idle", progress: 0 },
    ]);

    const runFLRound = () => {
        if (flStatus !== 'IDLE' && flStatus !== 'COMPLETE') return;
        setFlStatus('TRAINING');
        addLog(`[FL-SERVER] Commencing Global Epoch ${globalEpoch + 1}`);
        addLog("[FL-SERVER] Simulating Edge Secure Aggregation (SecAgg). Distributing global weights...");

        // Simulate training on nodes
        setNodes(n => n.map(x => ({ ...x, status: "Training (Local Data)", progress: 0 })));

        let p = 0;
        const interval = setInterval(() => {
            p += Math.random() * 15 + 10;
            if (p >= 100) {
                p = 100;
                clearInterval(interval);
                setNodes(n => n.map(x => ({ ...x, status: "Computing Gradient Delta...", progress: 100 })));
                setTimeout(() => {
                    setFlStatus('AGGREGATING');
                    addLog("[FL-SERVER] Receiving gradient updates (no raw data transferred)...");
                    setNodes(n => n.map(x => ({ ...x, status: "Uploading Encrypted Delta", progress: 100 })));

                    setTimeout(() => {
                        setGlobalEpoch(e => e + 1);
                        setFlStatus('COMPLETE');
                        addLog(`[FL-SERVER] Global Epoch ${globalEpoch + 1} finalized via Federated Averaging (FedAvg).`);
                        setNodes(n => n.map(x => ({ ...x, status: "Idle, awaiting next round.", progress: 0 })));
                    }, 2000);
                }, 1000);
            } else {
                setNodes(n => n.map(x => ({ ...x, progress: p })));
            }
        }, 300);
    };


    return (
        <div className="h-full flex flex-col space-y-8 bg-slate-50 p-6 rounded-2xl overflow-y-auto custom-scrollbar">

            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-2xl font-extrabold text-slate-900 flex items-center gap-3">
                        <TerminalWindowIcon /> Developer Sandbox
                    </h2>
                    <p className="text-sm text-slate-500 mt-1 font-medium">Interactive simulations for Edge Deployment & Privacy-Preserving AI</p>
                </div>
            </div>

            <div className="grid grid-cols-1 xl:grid-cols-2 gap-8">

                {/* Quantization Panel */}
                <div className="bg-white rounded-2xl border border-slate-200 shadow-sm p-6 overflow-hidden relative">
                    <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-50 rounded-full blur-3xl -mr-10 -mt-10" />

                    <div className="relative z-10 flex items-center justify-between mb-6">
                        <div className="flex items-center gap-2">
                            <Cpu className="w-5 h-5 text-indigo-600" />
                            <h3 className="font-bold text-slate-800 text-lg">Edge AI Quantization</h3>
                        </div>
                        <div className="flex items-center bg-slate-100 rounded-lg p-1 border border-slate-200">
                            <button
                                onClick={() => handleQuantize('FP32')}
                                className={`px-4 py-1.5 text-xs font-bold rounded-md transition-all ${precision === 'FP32' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                            >
                                FP32 (Cloud)
                            </button>
                            <button
                                onClick={() => handleQuantize('INT8')}
                                className={`px-4 py-1.5 text-xs font-bold rounded-md transition-all ${precision === 'INT8' ? 'bg-indigo-600 text-white shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                            >
                                INT8 (Edge)
                            </button>
                        </div>
                    </div>

                    <p className="text-sm text-slate-600 mb-6 font-medium">
                        Simulate compiling the PyTorch model for edge devices using Post-Training Quantization. INT8 dramatically reduces footprint for low-power hospital systems.
                    </p>

                    <div className="grid grid-cols-2 gap-4">
                        <MetricCard label="VRAM Usage" value={metrics.vram} icon={Database} color="indigo" />
                        <MetricCard label="Inference Latency" value={metrics.latency} icon={Zap} color="amber" />
                        <MetricCard label="Throughput" value={metrics.throughput} icon={ActivitySquare} color="emerald" />
                        <MetricCard label="Network Size" value={metrics.size} icon={Hexagon} color="rose" />
                    </div>
                </div>

                {/* Federated Learning Panel */}
                <div className="bg-white rounded-2xl border border-slate-200 shadow-sm p-6 overflow-hidden relative flex flex-col">
                    <div className="absolute top-0 right-0 w-32 h-32 bg-emerald-50 rounded-full blur-3xl -mr-10 -mt-10" />

                    <div className="relative z-10 flex items-center justify-between mb-6">
                        <div className="flex items-center gap-2">
                            <Network className="w-5 h-5 text-emerald-600" />
                            <h3 className="font-bold text-slate-800 text-lg">Federated Learning Sim</h3>
                        </div>
                        <button
                            onClick={runFLRound}
                            disabled={flStatus === 'TRAINING' || flStatus === 'AGGREGATING'}
                            className="flex items-center gap-2 px-4 py-2 bg-emerald-600 hover:bg-emerald-700 disabled:opacity-50 text-white rounded-lg text-xs font-bold shadow-sm transition-colors"
                        >
                            <Play className="w-3 h-3" fill="currentColor" />
                            {flStatus === 'IDLE' || flStatus === 'COMPLETE' ? "Run Global Epoch" : "Running..."}
                        </button>
                    </div>

                    <div className="flex-1 flex flex-col justify-between relative z-10">

                        {/* Central Server */}
                        <div className="flex flex-col items-center mb-6">
                            <div className={`p-4 rounded-2xl border-2 transition-colors ${flStatus === 'AGGREGATING' ? 'border-emerald-500 bg-emerald-50 shadow-[0_0_15px_rgba(16,185,129,0.2)]' : 'border-slate-200 bg-white'}`}>
                                <Server className={`w-8 h-8 ${flStatus === 'AGGREGATING' ? 'text-emerald-600 animate-pulse' : 'text-slate-400'}`} />
                            </div>
                            <span className="text-xs font-bold text-slate-700 mt-2 uppercase tracking-widest">Global SecAgg Server</span>
                            <span className="text-[10px] bg-slate-100 px-2 py-0.5 rounded text-slate-500 mt-1 font-mono">Epoch: {globalEpoch}</span>
                        </div>

                        {/* Connection Lines & Cloud */}
                        <div className="relative h-12 flex justify-center w-full">
                            {flStatus === 'TRAINING' && (
                                <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="absolute inset-0 flex justify-center items-center text-emerald-500">
                                    <DownloadCloud className="w-6 h-6 animate-bounce" />
                                </motion.div>
                            )}
                            {flStatus === 'AGGREGATING' && (
                                <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="absolute inset-0 flex justify-center items-center text-rose-500">
                                    <UploadCloud className="w-6 h-6 animate-bounce" />
                                </motion.div>
                            )}
                        </div>

                        {/* Nodes */}
                        <div className="grid grid-cols-3 gap-4">
                            {nodes.map((node, i) => (
                                <div key={i} className="bg-slate-50 border border-slate-200 rounded-xl p-3 text-center relative overflow-hidden">
                                    {/* Progress Bar Background */}
                                    <div className="absolute bottom-0 left-0 h-1 bg-emerald-500 transition-all duration-300" style={{ width: `${node.progress}%` }} />

                                    <ShieldCheck className="w-5 h-5 text-slate-400 mx-auto mb-2" />
                                    <h4 className="text-xs font-bold text-slate-700">{node.id}</h4>
                                    <p className="text-[10px] text-slate-500 mb-1">{node.data} Scans (Private)</p>
                                    <span className={`text-[9px] font-bold uppercase tracking-wider ${node.progress > 0 && node.progress < 100 ? 'text-indigo-600' : 'text-slate-400'}`}>
                                        {node.status}
                                    </span>
                                </div>
                            ))}
                        </div>

                    </div>
                </div>

            </div>

            {/* Terminal Window */}
            <div className="bg-[#0f172a] rounded-xl border border-slate-800 shadow-2xl flex flex-col overflow-hidden h-64 shrink-0">
                <div className="h-8 border-b border-slate-800 bg-[#020617] flex items-center px-4 justify-between">
                    <div className="flex items-center gap-2">
                        <div className="flex gap-1.5">
                            <div className="w-2.5 h-2.5 rounded-full bg-rose-500" />
                            <div className="w-2.5 h-2.5 rounded-full bg-amber-500" />
                            <div className="w-2.5 h-2.5 rounded-full bg-emerald-500" />
                        </div>
                        <span className="text-[10px] font-mono text-slate-500 ml-4 font-bold flex items-center gap-2 uppercase tracking-widest">
                            Server Logs
                        </span>
                    </div>
                </div>
                <div className="flex-1 p-4 overflow-y-auto custom-scrollbar font-mono text-xs flex flex-col justify-end">
                    <div className="space-y-1">
                        {qLogs.map((log, i) => (
                            <motion.div
                                key={i}
                                initial={{ opacity: 0, x: -10 }}
                                animate={{ opacity: 1, x: 0 }}
                                className={`
                                    ${log.includes('[ERROR]') ? 'text-rose-400' :
                                        log.includes('[WARN]') ? 'text-amber-400' :
                                            log.includes('[DEBUG]') ? 'text-slate-500' :
                                                log.includes('[FL-SERVER]') ? 'text-emerald-400 font-bold' :
                                                    log.includes('[SYSTEM]') ? 'text-cyan-400 font-bold' :
                                                        'text-indigo-300'
                                    } leading-relaxed
                                `}
                            >
                                <span className="opacity-50 text-slate-600 mr-2">root@node:~#</span>
                                {log}
                            </motion.div>
                        ))}
                    </div>
                </div>
            </div>

        </div>
    );
}

function TerminalWindowIcon() {
    return (
        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="text-indigo-600">
            <polyline points="4 17 10 11 4 5"></polyline>
            <line x1="12" y1="19" x2="20" y2="19"></line>
        </svg>
    )
}

function MetricCard({ label, value, icon: Icon, color }: { label: string, value: string, icon: any, color: 'indigo' | 'amber' | 'emerald' | 'rose' }) {

    const colorClasses = {
        indigo: 'text-indigo-600 bg-indigo-50 border-indigo-100',
        amber: 'text-amber-600 bg-amber-50 border-amber-100',
        emerald: 'text-emerald-600 bg-emerald-50 border-emerald-100',
        rose: 'text-rose-600 bg-rose-50 border-rose-100',
    };

    return (
        <div className={`p-4 rounded-xl border ${colorClasses[color]} transition-all duration-500`}>
            <div className="flex items-center gap-2 mb-2">
                <Icon className={`w-4 h-4 ${colorClasses[color].split(' ')[0]}`} />
                <span className="text-[10px] font-bold uppercase tracking-widest opacity-80">{label}</span>
            </div>
            <motion.div
                key={value}
                initial={{ opacity: 0, y: 5 }}
                animate={{ opacity: 1, y: 0 }}
                className="text-xl font-extrabold font-mono"
            >
                {value}
            </motion.div>
        </div>
    );
}

