import { useState, useCallback, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { UserPlus, Upload, AlertTriangle, Shield, CheckCircle, Image as ImageIcon, Sparkles, Database, ActivitySquare } from "lucide-react";
import { UploadZone } from "@/components/upload/upload-zone";
import { ImageViewer } from "@/components/viewer/image-viewer";
import { DiseaseTable } from "@/components/results/disease-table";
import { RiskBadge } from "@/components/results/risk-badge";
import { UncertaintyIndicator } from "@/components/results/uncertainty-indicator";
import { DiseaseTimeline } from "@/components/results/disease-timeline";
import { ReportDownload } from "@/components/report/report-download";
import { predictImage, getDemographicRiskAlert } from "@/lib/api";
import type { PredictionResponse, PatientDetails, ScanRecord } from "@/types";
import { ResultModal } from "@/components/results/result-modal";
import ReactMarkdown from "react-markdown";

interface NewScanProps {
    onAiSummaryClick: () => void;
    externalHistory: ScanRecord[];
    onHistoryUpdate: (history: ScanRecord[] | ((prev: ScanRecord[]) => ScanRecord[])) => void;
}

export function NewScan({ onAiSummaryClick, externalHistory, onHistoryUpdate }: NewScanProps) {
    const [patientData, setPatientData] = useState<PatientDetails>({
        name: "",
        age: "",
        gender: "",
        phone: "",
        address: "",
        symptoms: "",
        smoking_history: "Never"
    });

    const [file, setFile] = useState<File | null>(null);
    const [preview, setPreview] = useState<string | null>(null);
    const [result, setResult] = useState<PredictionResponse | null>(null);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [demoAlert, setDemoAlert] = useState<string | null>(null);
    const [loadingDemoAlert, setLoadingDemoAlert] = useState(false);

    // Modal State (History is now external)
    const [selectedScan, setSelectedScan] = useState<ScanRecord | null>(null);
    const [isModalOpen, setIsModalOpen] = useState(false);

    useEffect(() => {
        if (patientData.age && patientData.gender && parseInt(patientData.age) > 0) {
            setLoadingDemoAlert(true);
            const debounceTimer = setTimeout(async () => {
                try {
                    const res = await getDemographicRiskAlert(patientData.age || "", patientData.gender || "");
                    if (res?.alert && !res.alert.includes("sufficient demographic data")) {
                        setDemoAlert(res.alert);
                    } else {
                        setDemoAlert(null);
                    }
                } catch {
                    setDemoAlert(null);
                } finally {
                    setLoadingDemoAlert(false);
                }
            }, 1000); // 1s debounce
            return () => clearTimeout(debounceTimer);
        } else {
            setDemoAlert(null);
        }
    }, [patientData.age, patientData.gender]);

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setPatientData(prev => ({ ...prev, [name]: value }));
    };

    const handleAnalyze = useCallback(async (selectedFile: File) => {
        if (!patientData.name || !patientData.age || !patientData.gender) {
            setError("Please fill in required patient details (Name, Age, Gender) before uploading an image.");
            return;
        }

        setLoading(true);
        setError(null);

        try {
            const response = await predictImage(selectedFile, patientData);
            setResult(response);

            // Add to history
            const newRecord: ScanRecord = {
                id: response.report_id,
                timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
                patientName: patientData.name || "Anonymous",
                result: response,
                preview: URL.createObjectURL(selectedFile)
            };
            onHistoryUpdate(prev => [newRecord, ...prev]);
        } catch (err) {
            setError(err instanceof Error ? err.message : "Analysis failed");
        } finally {
            setLoading(false);
        }
    }, [patientData]);

    const handleFileSelect = useCallback((selectedFile: File) => {
        setFile(selectedFile);
        setPreview(URL.createObjectURL(selectedFile));
        setResult(null);
        setError(null);
        handleAnalyze(selectedFile); // Auto triggers analysis upon file select
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [handleAnalyze]);

    const handleReset = useCallback(() => {
        setFile(null);
        setPreview(null);
        setResult(null);
        setError(null);
        setPatientData({
            name: "",
            age: "",
            gender: "",
            phone: "",
            address: "",
            symptoms: "",
            smoking_history: "Never"
        });
    }, []);

    const handleAddMorePhotos = useCallback(() => {
        setFile(null);
        setPreview(null);
        setResult(null);
        setError(null);
    }, []);

    const handleViewReport = (scan: ScanRecord) => {
        setSelectedScan(scan);
        setIsModalOpen(true);
    };

    return (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 relative z-10 w-full mb-10">
            {/* ΓòÉΓòÉΓòÉ LEFT PANEL (7 columns) ΓòÉΓòÉΓòÉ */}
            <div className="lg:col-span-7 space-y-6">

                {/* AI Demographic Alert */}
                <AnimatePresence>
                    {(demoAlert || loadingDemoAlert) && (
                        <motion.div
                            initial={{ opacity: 0, height: 0, scale: 0.95 }}
                            animate={{ opacity: 1, height: "auto", scale: 1 }}
                            exit={{ opacity: 0, height: 0, scale: 0.95 }}
                            className="overflow-hidden"
                        >
                            <div className="p-4 rounded-xl border border-amber-200 bg-amber-50 shadow-sm flex items-start gap-4">
                                <div className="mt-0.5">
                                    <AlertTriangle className={`w-5 h-5 ${loadingDemoAlert ? 'text-slate-400 animate-pulse' : 'text-amber-500'}`} />
                                </div>
                                <div className="flex-1">
                                    <h4 className="text-sm font-bold text-amber-900 mb-1 flex items-center gap-2">
                                        ΓÜá∩╕Å AI Demographic Risk Alert
                                        <span className="bg-amber-100/80 text-amber-700 text-[10px] px-2 py-0.5 rounded-full uppercase tracking-wider font-bold">Local Dataset Analysis</span>
                                    </h4>
                                    <p className={`text-sm font-medium leading-relaxed ${loadingDemoAlert ? 'text-amber-700/50' : 'text-amber-800'}`}>
                                        {loadingDemoAlert ? 'Synthesizing NIH dataset risk patterns...' : demoAlert}
                                    </p>
                                </div>
                            </div>
                        </motion.div>
                    )}
                </AnimatePresence>

                {/* Registration Form */}
                <div className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm relative overflow-hidden">
                    <div className="absolute top-0 left-0 w-1 h-full bg-blue-500" />

                    <div className="flex items-center gap-3 mb-6 pb-4 border-b border-slate-100">
                        <div className="w-10 h-10 rounded-xl bg-blue-50 flex items-center justify-center">
                            <UserPlus className="w-5 h-5 text-blue-600" />
                        </div>
                        <div>
                            <h3 className="text-lg font-bold text-slate-900">Patient Registration</h3>
                            <p className="text-xs text-slate-500 font-medium tracking-wide uppercase">Step 1: Clinical Demographics</p>
                        </div>
                    </div>

                    <form className="space-y-5">
                        <div>
                            <label className="block text-sm font-bold text-slate-700 mb-1.5">Full Name *</label>
                            <input
                                type="text"
                                name="name"
                                value={patientData.name}
                                onChange={handleInputChange}
                                disabled={loading || !!result}
                                className="w-full px-4 py-2.5 rounded-xl border border-slate-200 bg-slate-50 focus:bg-white focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all outline-none"
                            />
                        </div>

                        <div className="grid grid-cols-2 gap-5">
                            <div>
                                <label className="block text-sm font-bold text-slate-700 mb-1.5">Age *</label>
                                <input
                                    type="number"
                                    name="age"
                                    value={patientData.age}
                                    onChange={handleInputChange}
                                    disabled={loading || !!result}
                                    className="w-full px-4 py-2.5 rounded-xl border border-slate-200 bg-slate-50 focus:bg-white focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all outline-none"
                                    placeholder="Years"
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-bold text-slate-700 mb-1.5">Gender *</label>
                                <select
                                    name="gender"
                                    value={patientData.gender}
                                    onChange={handleInputChange}
                                    disabled={loading || !!result}
                                    className="w-full px-4 py-2.5 rounded-xl border border-slate-200 bg-slate-50 focus:bg-white focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all outline-none appearance-none"
                                >
                                    <option value="" disabled>Select</option>
                                    <option value="Male">Male</option>
                                    <option value="Female">Female</option>
                                    <option value="Other">Other</option>
                                </select>
                            </div>
                        </div>

                        <div>
                            <label className="block text-sm font-bold text-slate-700 mb-1.5">Phone Number</label>
                            <input
                                type="tel"
                                name="phone"
                                value={patientData.phone}
                                onChange={handleInputChange}
                                disabled={loading || !!result}
                                className="w-full px-4 py-2.5 rounded-xl border border-slate-200 bg-slate-50 focus:bg-white focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all outline-none"
                            />
                        </div>

                        <div>
                            <label className="block text-sm font-bold text-slate-700 mb-1.5">Residential Address (Optional)</label>
                            <textarea
                                name="address"
                                value={patientData.address}
                                onChange={handleInputChange}
                                disabled={loading || !!result}
                                rows={2}
                                className="w-full px-4 py-2.5 rounded-xl border border-slate-200 bg-slate-50 focus:bg-white focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all outline-none resize-none"
                                placeholder="Enter address..."
                            />
                        </div>

                        <div className="grid grid-cols-2 gap-5 mt-4 pt-4 border-t border-slate-100">
                            <div className="col-span-2">
                                <label className="block text-sm font-bold text-indigo-700 mb-1.5 flex items-center gap-2">
                                    <ActivitySquare className="w-4 h-4" />
                                    Clinical Context
                                </label>
                                <p className="text-xs text-slate-500 mb-3">Adding context helps the AI act as a holistic second reader.</p>
                            </div>

                            <div className="col-span-2">
                                <label className="block text-sm font-bold text-slate-700 mb-1.5">Current Symptoms (Optional)</label>
                                <input
                                    type="text"
                                    name="symptoms"
                                    value={patientData.symptoms}
                                    onChange={handleInputChange}
                                    disabled={loading || !!result}
                                    className="w-full px-4 py-2.5 rounded-xl border border-slate-200 bg-slate-50 focus:bg-white focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all outline-none"
                                    placeholder="e.g., Persistent cough, fever, shortness of breath..."
                                />
                            </div>

                            <div className="col-span-2">
                                <label className="block text-sm font-bold text-slate-700 mb-1.5">Smoking History</label>
                                <select
                                    name="smoking_history"
                                    value={patientData.smoking_history}
                                    onChange={handleInputChange}
                                    disabled={loading || !!result}
                                    className="w-full px-4 py-2.5 rounded-xl border border-slate-200 bg-slate-50 focus:bg-white focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all outline-none appearance-none"
                                >
                                    <option value="Never">Never Smoked</option>
                                    <option value="Former">Former Smoker</option>
                                    <option value="Current (Occasional)">Current (Occasional)</option>
                                    <option value="Current (Heavy)">Current (Heavy)</option>
                                </select>
                            </div>
                        </div>
                    </form>
                </div>

                {/* Upload Section */}
                <div className={`rounded-2xl border ${!patientData.name || !patientData.age || !patientData.gender ? 'border-dashed border-slate-300 bg-slate-50/50 opacity-60 pointer-events-none' : 'border-slate-200 bg-white shadow-sm'} p-6 transition-all duration-300 relative`}>
                    {(!patientData.name || !patientData.age || !patientData.gender) && !result && (
                        <div className="absolute inset-0 flex items-center justify-center z-10 bg-slate-50/50 backdrop-blur-[1px] rounded-2xl">
                            <div className="bg-white px-4 py-2 rounded-full border border-slate-200 shadow-sm text-sm font-bold text-slate-500 flex items-center gap-2">
                                <Shield className="w-4 h-4 text-emerald-500" />
                                Complete Profile First
                            </div>
                        </div>
                    )}

                    <div className="flex items-center justify-between mb-5">
                        <div className="flex items-center gap-3">
                            <div className="w-10 h-10 rounded-xl bg-indigo-50 flex items-center justify-center">
                                <Upload className="w-5 h-5 text-indigo-600" />
                            </div>
                            <div>
                                <h3 className="text-lg font-bold text-slate-900">Upload Radiograph</h3>
                                <p className="text-xs text-slate-500 font-medium tracking-wide uppercase">Step 2: Auto-Analysis</p>
                            </div>
                        </div>
                    </div>

                    {!result && (
                        <UploadZone
                            onFileSelect={handleFileSelect}
                            file={file}
                            onReset={handleReset}
                        />
                    )}

                    {loading && (
                        <div className="mt-6 py-6 rounded-xl bg-blue-50/50 border border-blue-100 flex flex-col items-center justify-center gap-4 text-center">
                            <div className="relative w-12 h-12">
                                <div className="absolute inset-0 rounded-full border-4 border-blue-100" />
                                <div className="absolute inset-0 rounded-full border-4 border-blue-600 border-t-transparent animate-spin" />
                            </div>
                            <div>
                                <h4 className="text-sm text-blue-900 font-bold mb-1">Synthesizing AI Heatmaps</h4>
                                <p className="text-xs text-blue-700/80 font-medium">Running ensemble diagnostic models...</p>
                            </div>
                        </div>
                    )}

                    {error && (
                        <motion.div
                            initial={{ opacity: 0 }}
                            animate={{ opacity: 1 }}
                            className="mt-4 p-4 rounded-xl bg-red-50 border border-red-200 text-red-700 text-sm font-medium shadow-sm"
                        >
                            <div className="flex items-center gap-2 mb-1">
                                <AlertTriangle className="w-4 h-4" />
                                <span className="font-bold border-b border-red-200">Processing Error</span>
                            </div>
                            {error}
                        </motion.div>
                    )}

                    {/* Success Actions */}
                    {result && !loading && (
                        <motion.div
                            initial={{ opacity: 0, scale: 0.95 }}
                            animate={{ opacity: 1, scale: 1 }}
                            className="mt-4 p-5 rounded-xl border border-emerald-200 bg-emerald-50/50 space-y-4 shadow-inner"
                        >
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 rounded-full bg-emerald-100 flex items-center justify-center shrink-0">
                                    <CheckCircle className="w-5 h-5 text-emerald-600" />
                                </div>
                                <div>
                                    <h4 className="font-bold text-emerald-900">Processing Complete!</h4>
                                    <p className="text-xs text-emerald-700 font-medium">Report generated and securely logged.</p>
                                </div>
                            </div>

                            <div className="grid grid-cols-1 md:grid-cols-3 gap-3 pt-2 border-t border-emerald-100/50">
                                <button
                                    onClick={handleReset}
                                    className="w-full py-2.5 bg-white border border-slate-200 rounded-lg text-sm font-bold text-slate-700 hover:bg-slate-50 transition-colors shadow-sm cursor-pointer"
                                >
                                    New Patient
                                </button>
                                <button
                                    onClick={handleAddMorePhotos}
                                    className="w-full py-2.5 bg-white border border-slate-200 rounded-lg text-sm font-bold text-slate-700 hover:bg-slate-50 transition-colors shadow-sm cursor-pointer"
                                >
                                    Add Scans
                                </button>
                                <button
                                    onClick={onAiSummaryClick}
                                    className="w-full py-2.5 bg-indigo-600 border border-indigo-700 rounded-lg text-sm font-bold text-white hover:bg-indigo-700 transition-colors shadow-sm shadow-indigo-200"
                                >
                                    AI Summary
                                </button>
                            </div>
                        </motion.div>
                    )}
                </div>

            </div>

            {/* ΓòÉΓòÉΓòÉ RIGHT PANEL (5 columns) ΓòÉΓòÉΓòÉ */}
            <div className="lg:col-span-5 space-y-6 sticky top-24">
                <div className="flex items-center justify-between mb-2">
                    <h3 className="text-lg font-bold text-slate-900 flex items-center gap-2">
                        <ActivitySquare className="w-5 h-5 text-indigo-600" />
                        Session Scan History
                    </h3>
                    <span className="px-2.5 py-1 bg-slate-100 rounded-full text-[10px] font-bold text-slate-500 uppercase tracking-wider">
                        {externalHistory.length} Scans Found
                    </span>
                </div>

                <div className="space-y-4">
                    <AnimatePresence mode="popLayout">
                        {externalHistory.length > 0 ? (
                            externalHistory.map((scan) => (
                                <motion.div
                                    key={scan.id}
                                    initial={{ opacity: 0, y: 10 }}
                                    animate={{ opacity: 1, y: 0 }}
                                    exit={{ opacity: 0, scale: 0.95 }}
                                    layout
                                    className="group relative bg-white border border-slate-200 rounded-2xl p-4 shadow-sm hover:shadow-md hover:border-indigo-200 transition-all cursor-pointer"
                                    onClick={() => handleViewReport(scan)}
                                >
                                    <div className="flex gap-4">
                                        <div className="w-20 h-20 rounded-xl bg-slate-900 overflow-hidden border border-slate-100 flex-shrink-0">
                                            <img
                                                src={scan.preview}
                                                alt="X-ray preview"
                                                className="w-full h-full object-cover opacity-80 group-hover:opacity-100 transition-opacity"
                                            />
                                        </div>
                                        <div className="flex-1 min-w-0">
                                            <div className="flex items-start justify-between mb-1">
                                                <div>
                                                    <h4 className="font-bold text-slate-900 truncate pr-2">
                                                        {scan.patientName}
                                                    </h4>
                                                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                                                        ID: {scan.id.substring(0, 8)}
                                                    </p>
                                                </div>
                                                <span className="text-[10px] font-bold text-slate-400">
                                                    {scan.timestamp}
                                                </span>
                                            </div>

                                            <div className="flex items-center gap-3 mt-2">
                                                <div className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-wider border ${scan.result.risk_assessment.risk_level === "High Suspicion"
                                                    ? "bg-red-50 text-red-600 border-red-100"
                                                    : scan.result.risk_assessment.risk_level === "Moderate Risk"
                                                        ? "bg-amber-50 text-amber-600 border-amber-100"
                                                        : "bg-emerald-50 text-emerald-600 border-emerald-100"
                                                    }`}>
                                                    {scan.result.risk_assessment.risk_level}
                                                </div>
                                                <button
                                                    onClick={(e) => {
                                                        e.stopPropagation();
                                                        onAiSummaryClick();
                                                    }}
                                                    className="flex items-center gap-1.5 text-[10px] font-bold text-indigo-500 uppercase hover:text-indigo-700 transition-colors"
                                                >
                                                    <Sparkles className="w-3 h-3" />
                                                    View Clinical Summary
                                                </button>
                                            </div>
                                        </div>
                                    </div>

                                    <div className="absolute top-4 right-4 opacity-0 group-hover:opacity-100 transition-opacity">
                                        <div className="w-8 h-8 rounded-full bg-indigo-50 flex items-center justify-center">
                                            <Sparkles className="w-4 h-4 text-indigo-600" />
                                        </div>
                                    </div>
                                </motion.div>
                            ))
                        ) : (
                            <motion.div
                                initial={{ opacity: 0 }}
                                animate={{ opacity: 1 }}
                                className="flex flex-col items-center justify-center py-16 px-6 rounded-2xl border-2 border-dashed border-slate-200 bg-slate-50/50"
                            >
                                <div className="w-16 h-16 rounded-2xl bg-white flex items-center justify-center mb-4 border border-slate-100 shadow-sm">
                                    <ActivitySquare className="w-8 h-8 text-slate-300" />
                                </div>
                                <h3 className="text-sm font-bold text-slate-900 mb-1">No Scans This Session</h3>
                                <p className="text-slate-500 text-center text-xs font-medium max-w-[200px]">
                                    Complete a patient registration and upload an X-ray to see results here.
                                </p>
                            </motion.div>
                        )}
                    </AnimatePresence>
                </div>
            </div>

            {/* Result Modal */}
            <ResultModal
                isOpen={isModalOpen}
                onClose={() => setIsModalOpen(false)}
                result={selectedScan?.result || null}
                previewUrl={selectedScan?.preview || null}
            />
        </div>
    );
}

import { useState, useEffect } from "react";
import { format } from "date-fns";
import { Download, FileText, Loader2, AlertCircle, Eye, X, Activity, TrendingUp, TrendingDown } from "lucide-react";
import { getReports, downloadReportPdf } from "@/lib/api";
import type { Report } from "@/types";
import { Portal } from "@/components/ui/portal";

export function PatientReports() {
    const [reports, setReports] = useState<Report[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [downloadingId, setDownloadingId] = useState<string | null>(null);
    const [viewingId, setViewingId] = useState<string | null>(null);
    const [viewPdfUrl, setViewPdfUrl] = useState<string | null>(null);
    const [selectedPatient, setSelectedPatient] = useState<string | null>(null);

    useEffect(() => {
        fetchReports();
    }, []);

    const fetchReports = async () => {
        try {
            setLoading(true);
            setError(null);
            const data = await getReports();
            const namedPatientData = data.filter(r => r.patient_details?.name);
            namedPatientData.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
            setReports(namedPatientData);
        } catch (err) {
            setError(err instanceof Error ? err.message : "Failed to load reports");
        } finally {
            setLoading(false);
        }
    };

    const handleDownload = async (reportId: string) => {
        try {
            setDownloadingId(reportId);
            const blob = await downloadReportPdf(reportId);

            const url = window.URL.createObjectURL(blob);
            const a = document.createElement("a");
            a.href = url;
            a.download = `Wavelength_Report_${reportId}.pdf`;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            window.URL.revokeObjectURL(url);
        } catch (err) {
            alert("Failed to download PDF report. Please try again.");
        } finally {
            setDownloadingId(null);
        }
    };

    const handleView = async (reportId: string) => {
        try {
            setViewingId(reportId);
            const blob = await downloadReportPdf(reportId);
            const url = window.URL.createObjectURL(blob);
            setViewPdfUrl(url);
        } catch (err) {
            alert("Failed to load PDF report for viewing.");
        } finally {
            setViewingId(null);
        }
    };

    if (loading) {
        return (
            <div className="flex flex-col items-center justify-center h-[600px]">
                <Loader2 className="w-8 h-8 text-blue-600 animate-spin mb-4" />
                <p className="text-slate-500 font-medium">Loading patient history...</p>
            </div>
        );
    }

    if (error) {
        return (
            <div className="flex flex-col items-center justify-center h-[600px] text-red-600">
                <AlertCircle className="w-10 h-10 mb-2" />
                <p className="font-bold">{error}</p>
                <button
                    onClick={fetchReports}
                    className="mt-4 px-4 py-2 bg-slate-100 text-slate-700 rounded-md hover:bg-slate-200 font-medium"
                >
                    Try Again
                </button>
            </div>
        );
    }

    return (
        <div className="bg-white rounded-2xl border border-[#e2e8f0] shadow-sm overflow-hidden">
            <div className="p-6 border-b border-[#e2e8f0] flex items-center justify-between bg-slate-50">
                <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-xl bg-indigo-100 flex items-center justify-center">
                        <FileText className="w-5 h-5 text-indigo-600" />
                    </div>
                    <div>
                        <h2 className="text-xl font-bold text-slate-900">Patient Directory</h2>
                        <p className="text-sm text-slate-500">Comprehensive list of all AI analyzed cases.</p>
                    </div>
                </div>
                <div className="px-3 py-1 bg-white border border-slate-200 rounded-full text-xs font-bold text-slate-600 shadow-sm">
                    {reports.length} Records
                </div>
            </div>

            <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                    <thead>
                        <tr className="bg-slate-50 border-b border-slate-200">
                            <th className="py-4 px-6 font-bold text-xs uppercase tracking-wider text-slate-500">Date/Time</th>
                            <th className="py-4 px-6 font-bold text-xs uppercase tracking-wider text-slate-500">Report ID</th>
                            <th className="py-4 px-6 font-bold text-xs uppercase tracking-wider text-slate-500">Patient Info</th>
                            <th className="py-4 px-6 font-bold text-xs uppercase tracking-wider text-slate-500">Risk Assessment</th>
                            <th className="py-4 px-6 font-bold text-xs uppercase tracking-wider text-slate-500 text-right">Action</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {reports.length === 0 ? (
                            <tr>
                                <td colSpan={5} className="py-12 text-center text-slate-500 font-medium">
                                    No patient reports found in the database.
                                </td>
                            </tr>
                        ) : (
                            reports.map((report) => (
                                <tr key={report.report_id} className="hover:bg-slate-50/50 transition-colors">
                                    <td className="py-4 px-6 whitespace-nowrap">
                                        <div className="text-sm font-bold text-slate-800">
                                            {format(new Date(report.timestamp), "MMM dd, yyyy")}
                                        </div>
                                        <div className="text-xs text-slate-500 font-medium">
                                            {format(new Date(report.timestamp), "hh:mm a")}
                                        </div>
                                    </td>
                                    <td className="py-4 px-6 whitespace-nowrap">
                                        <span className="font-mono text-sm bg-slate-100 px-2 py-1 rounded text-slate-700 border border-slate-200">
                                            {report.report_id}
                                        </span>
                                    </td>
                                    <td className="py-4 px-6">
                                        {report.patient_details?.name ? (
                                            <div>
                                                <button
                                                    onClick={() => setSelectedPatient(report.patient_details?.name || null)}
                                                    className="text-sm font-bold text-indigo-600 hover:text-indigo-800 underline decoration-indigo-200 underline-offset-4 text-left focus:outline-none"
                                                >
                                                    {report.patient_details.name}
                                                </button>
                                                <div className="text-xs text-slate-500 font-medium mt-0.5">
                                                    {report.patient_details.age ? `${report.patient_details.age}y` : ''}
                                                    {report.patient_details.gender ? ` ΓÇó ${report.patient_details.gender}` : ''}
                                                </div>
                                            </div>
                                        ) : (
                                            <span className="text-sm italic text-slate-400">Anonymous Scan</span>
                                        )}
                                    </td>
                                    <td className="py-4 px-6 whitespace-nowrap">
                                        <div className="flex items-center gap-2">
                                            <div className="w-2 h-2 rounded-full" style={{ backgroundColor: report.risk_assessment.risk_color }} />
                                            <span className="text-sm font-bold text-slate-700">
                                                {report.risk_assessment.risk_level}
                                            </span>
                                        </div>
                                    </td>
                                    <td className="py-4 px-6 whitespace-nowrap text-right">
                                        <div className="flex items-center justify-end gap-2">
                                            <button
                                                onClick={() => handleView(report.report_id)}
                                                disabled={viewingId === report.report_id}
                                                className="inline-flex items-center justify-center gap-2 px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm font-bold text-slate-700 hover:bg-slate-100 transition-colors disabled:opacity-50 disabled:cursor-not-allowed shadow-sm"
                                            >
                                                {viewingId === report.report_id ? (
                                                    <Loader2 className="w-4 h-4 animate-spin" />
                                                ) : (
                                                    <Eye className="w-4 h-4" />
                                                )}
                                                View
                                            </button>
                                            <button
                                                onClick={() => handleDownload(report.report_id)}
                                                disabled={downloadingId === report.report_id}
                                                className="inline-flex items-center justify-center gap-2 px-3 py-2 bg-white border border-slate-200 rounded-lg text-sm font-bold text-[#1e3a8a] hover:bg-blue-50 hover:border-blue-200 transition-colors disabled:opacity-50 disabled:cursor-not-allowed shadow-sm"
                                            >
                                                {downloadingId === report.report_id ? (
                                                    <Loader2 className="w-4 h-4 animate-spin" />
                                                ) : (
                                                    <Download className="w-4 h-4" />
                                                )}
                                                Export
                                            </button>
                                        </div>
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            </div>

            {viewPdfUrl && (
                <Portal>
                    <div className="fixed inset-0 z-[1000] flex items-center justify-center bg-slate-900/50 backdrop-blur-sm p-4">
                        <div className="bg-white rounded-2xl w-full max-w-5xl h-[90vh] flex flex-col overflow-hidden shadow-2xl border border-slate-200">
                            <div className="p-4 border-b border-slate-200 flex justify-between items-center bg-slate-50">
                                <h3 className="font-bold text-slate-800 flex items-center gap-2">
                                    <FileText className="w-5 h-5 text-indigo-600" />
                                    Clinical Report Preview
                                </h3>
                                <button
                                    onClick={() => {
                                        window.URL.revokeObjectURL(viewPdfUrl);
                                        setViewPdfUrl(null);
                                    }}
                                    className="p-2 hover:bg-slate-200 rounded-full transition-colors group"
                                >
                                    <X className="w-5 h-5 text-slate-500 group-hover:text-slate-700" />
                                </button>
                            </div>
                            <iframe src={viewPdfUrl} className="w-full flex-1 border-0" title="PDF Report Preview" />
                        </div>
                    </div>
                </Portal>
            )}

            {/* Longitudinal Progression Modal */}
            {selectedPatient && (() => {
                const timeline = reports.filter(r => r.patient_details?.name === selectedPatient).sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime());
                return (
                    <Portal>
                        <div className="fixed inset-0 z-[1000] flex items-center justify-center bg-slate-900/50 backdrop-blur-sm p-4">
                            <div className="bg-white rounded-2xl w-full max-w-4xl max-h-[90vh] flex flex-col overflow-hidden shadow-2xl border border-slate-200">
                                <div className="p-6 border-b border-slate-200 flex justify-between items-center bg-slate-50">
                                    <h3 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                                        <Activity className="w-6 h-6 text-indigo-600" />
                                        Longitudinal Progression: {selectedPatient}
                                    </h3>
                                    <button onClick={() => setSelectedPatient(null)} className="p-2 hover:bg-slate-200 rounded-full transition-colors group focus:outline-none">
                                        <X className="w-5 h-5 text-slate-500 group-hover:text-slate-700" />
                                    </button>
                                </div>
                                <div className="flex-1 overflow-y-auto p-8 bg-slate-50/50 space-y-8">
                                    {timeline.map((rpt, idx) => {
                                        const prevRpt = idx > 0 ? timeline[idx - 1] : null;
                                        // Hack to access severity_index via risk_assessment any, or optional chaining
                                        const currentRSI = (rpt.risk_assessment as any)?.severity_index;
                                        const prevRSI = (prevRpt?.risk_assessment as any)?.severity_index;

                                        let rsiDelta = null;
                                        if (currentRSI !== undefined && prevRSI !== undefined) {
                                            rsiDelta = currentRSI - prevRSI;
                                        }

                                        return (
                                            <div key={rpt.report_id} className="relative pl-8">
                                                {/* Connecting Line */}
                                                {idx !== timeline.length - 1 && (
                                                    <div className="absolute left-[3px] top-8 bottom-[-2rem] w-[2px] bg-indigo-100" />
                                                )}
                                                {/* Dot */}
                                                <div className="absolute left-[-2px] top-6 w-3 h-3 rounded-full bg-indigo-500 ring-4 ring-slate-50" />

                                                <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm transition-shadow hover:shadow-md">
                                                    <div className="flex justify-between items-start mb-4">
                                                        <div>
                                                            <div className="text-sm font-bold text-slate-500 mb-1">{format(new Date(rpt.timestamp), "MMM dd, yyyy ΓÇó hh:mm a")}</div>
                                                            <h4 className="text-lg font-extrabold text-slate-800">Scan ID: {rpt.report_id}</h4>
                                                        </div>
                                                        <div className="text-right">
                                                            <div className="inline-flex items-center gap-1.5 px-3 py-1 bg-slate-100 rounded-full mb-2">
                                                                <span className="w-2 h-2 rounded-full" style={{ backgroundColor: rpt.risk_assessment?.risk_color }} />
                                                                <span className="text-xs font-bold text-slate-700">{rpt.risk_assessment?.risk_level}</span>
                                                            </div>
                                                            {currentRSI !== undefined && (
                                                                <div className="text-sm font-bold text-slate-600 flex items-center justify-end gap-2">
                                                                    <span>RSI: {Number(currentRSI).toFixed(1)}</span>
                                                                    {rsiDelta !== null && Math.abs(rsiDelta) > 0.1 && (
                                                                        <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-extrabold ${rsiDelta > 0 ? 'bg-rose-100 text-rose-700' : 'bg-emerald-100 text-emerald-700'}`}>
                                                                            {rsiDelta > 0 ? <TrendingUp className="w-3 h-3" /> : <TrendingDown className="w-3 h-3" />}
                                                                            {Math.abs(rsiDelta).toFixed(1)}
                                                                        </span>
                                                                    )}
                                                                </div>
                                                            )}
                                                        </div>
                                                    </div>
                                                    <div className="grid grid-cols-2 gap-4 mt-4">
                                                        <div className="bg-slate-50 p-4 rounded-xl border border-slate-100">
                                                            <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest block mb-2">Primary Findings & Confidence</span>
                                                            <div className="flex flex-wrap gap-2">
                                                                {Object.entries(rpt.disease_probabilities || {}).filter(([_, p]) => (p as number) > 0.5).map(([d, p]) => (
                                                                    <span key={d} className="px-2 py-1 bg-white border border-slate-200 rounded text-xs font-bold text-slate-700 shadow-sm">
                                                                        {d} ({(p as number * 100).toFixed(1)}%)
                                                                    </span>
                                                                ))}
                                                                {Object.entries(rpt.disease_probabilities || {}).filter(([_, p]) => (p as number) > 0.5).length === 0 && (
                                                                    <span className="text-sm font-medium text-slate-500 italic">No acute findings.</span>
                                                                )}
                                                            </div>
                                                        </div>
                                                        <div className="bg-indigo-50/50 p-4 rounded-xl border border-indigo-100">
                                                            <span className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest block mb-2">AI Clinical Synthesis</span>
                                                            <p className="text-sm font-medium text-slate-700 line-clamp-3">
                                                                {rpt.ai_summary ? rpt.ai_summary.substring(0, 150) + "..." : "AI Summary unavailable or currently synthesizing."}
                                                            </p>
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>
                            </div>
                        </div>
                    </Portal>
                );
            })()}
        </div>
    );
}

import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Target, Award, RefreshCw, CheckCircle, XCircle, ChevronRight, Activity } from "lucide-react";
import ReactMarkdown from "react-markdown";
import { getTutorFeedback } from "@/lib/api";

const TRAINING_CASES = [
    { img: "/dataset/CHNCXR_0065_0.png", trueLabel: "Mass", desc: "Large mass in the left upper lobe, suspicious for malignancy. Notice the defined borders." },
    { img: "/dataset/CHNCXR_0036_0.png", trueLabel: "Cardiomegaly", desc: "Enlarged cardiac silhouette with CTR > 0.5. The heart spans more than half the thoracic width." },
    { img: "/dataset/CHNCXR_0040_0.png", trueLabel: "Effusion", desc: "Blunting of the costophrenic angles indicative of pleural fluid collection." },
    { img: "/dataset/CHNCXR_0185_0.png", trueLabel: "Pneumonia", desc: "Alveolar consolidation in the mid lung zone with air bronchograms." },
    { img: "/dataset/CHNCXR_0193_0.png", trueLabel: "Atelectasis", desc: "Volume loss in the upper lobe. Note the compensative hyperexpansion of adjacent tissue." },
    { img: "/dataset/CHNCXR_0488_1.png", trueLabel: "Cardiomegaly", desc: "Massive 'water-bottle' shaped heart typical of pericardial effusion or severe cardiomegaly." },
    { img: "/dataset/CHNCXR_0561_1.png", trueLabel: "Pneumonia", desc: "Dense opacification covering major portions of the right lobe. Complete lobar consolidation." },
    { img: "/dataset/CHNCXR_0211_0.png", trueLabel: "Effusion", desc: "Meniscus sign perfectly visible against the lateral thoracic wall." }
];

const LABELS = ["No Finding", "Atelectasis", "Cardiomegaly", "Effusion", "Infiltration", "Mass", "Nodule", "Pneumonia"];

export function TrainingMode() {
    const [currentIndex, setCurrentIndex] = useState(0);
    const [score, setScore] = useState({ correct: 0, total: 0 });
    const [guess, setGuess] = useState<string | null>(null);
    const [tutorFeedback, setTutorFeedback] = useState<string | null>(null);
    const [loadingTutor, setLoadingTutor] = useState(false);

    const activeCase = TRAINING_CASES[currentIndex];
    const isRevealed = guess !== null;
    const isCorrect = guess === activeCase.trueLabel;

    const handleGuess = async (label: string) => {
        if (isRevealed) return;
        setGuess(label);
        const correct = label === activeCase.trueLabel;
        setScore(curr => ({
            correct: curr.correct + (correct ? 1 : 0),
            total: curr.total + 1
        }));

        setLoadingTutor(true);
        setTutorFeedback(null);
        try {
            const res = await getTutorFeedback(label, activeCase.trueLabel, activeCase.desc);
            setTutorFeedback(res.feedback);
        } catch (e) {
            setTutorFeedback("Tutor is currently unavailable.");
        } finally {
            setLoadingTutor(false);
        }
    };

    const nextCase = () => {
        setGuess(null);
        setTutorFeedback(null);
        setCurrentIndex((prev) => (prev + 1) % TRAINING_CASES.length);
    };

    return (
        <div className="flex flex-col h-full relative">
            <div className="flex justify-between items-center mb-8">
                <div>
                    <h2 className="text-3xl font-bold text-slate-900 tracking-tight">Resident Training Ground</h2>
                    <p className="text-slate-500 font-medium">Test your radiologic diagnostic acumen against NIH verified cases.</p>
                </div>

                {/* Score and Controls */}
                <div className="flex flex-col sm:flex-row shadow-sm gap-4 items-center sm:items-stretch">
                    <button
                        onClick={nextCase}
                        className="bg-white px-5 rounded-2xl border border-slate-200 text-slate-700 font-bold hover:bg-slate-50 hover:border-slate-300 transition-colors flex items-center justify-center gap-2"
                    >
                        Next Case <ChevronRight className="w-4 h-4" />
                    </button>

                    <div className="flex items-center gap-4 bg-white px-5 py-3 rounded-2xl border border-slate-200">
                        <div className="flex items-center gap-2">
                            <Award className="w-6 h-6 text-yellow-500" />
                            <div>
                                <div className="text-sm font-bold text-slate-500 uppercase tracking-wider mb-0.5">Accuracy</div>
                                <div className="text-2xl font-black text-slate-900 leading-none">
                                    {score.total === 0 ? "0%" : `${Math.round((score.correct / score.total) * 100)}%`}
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 flex-1">

                {/* Image Panel */}
                <div className="bg-slate-900 rounded-3xl overflow-hidden relative border border-slate-200 shadow-sm flex items-center justify-center min-h-[500px]">
                    <AnimatePresence mode="wait">
                        <motion.img
                            key={activeCase.img}
                            src={activeCase.img}
                            initial={{ opacity: 0, scale: 0.95 }}
                            animate={{ opacity: 1, scale: 1 }}
                            exit={{ opacity: 0 }}
                            transition={{ duration: 0.4 }}
                            className={`w-full h-full object-contain p-4 ${isRevealed ? "" : "grayscale"}`}
                            alt="Training Case"
                        />
                    </AnimatePresence>

                    {/* HUD Overlay */}
                    <div className="absolute top-4 left-4 flex gap-2">
                        <div className="bg-black/60 backdrop-blur text-white text-xs font-bold px-3 py-1.5 rounded-full uppercase tracking-wider border border-white/20">
                            Case #{currentIndex + 1}
                        </div>
                        {isRevealed && (
                            <motion.div
                                initial={{ opacity: 0, scale: 0.8 }}
                                animate={{ opacity: 1, scale: 1 }}
                                className={`text-xs font-bold px-3 py-1.5 rounded-full uppercase tracking-wider border flex items-center gap-1 ${isCorrect ? "bg-emerald-500/20 text-emerald-400 border-emerald-500/50" : "bg-red-500/20 text-red-400 border-red-500/50"}`}
                            >
                                {isCorrect ? <CheckCircle className="w-3.5 h-3.5" /> : <XCircle className="w-3.5 h-3.5" />}
                                {isCorrect ? "Correct Diagnosis" : "Misdiagnosis"}
                            </motion.div>
                        )}
                    </div>
                </div>

                {/* Interaction Panel */}
                <div className="flex flex-col gap-6">
                    <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
                        <h3 className="text-lg font-bold text-slate-900 mb-2 flex items-center gap-2">
                            <Target className="w-5 h-5 text-indigo-500" />
                            Primary Finding
                        </h3>
                        <p className="text-sm text-slate-500 mb-6">Analyze the radiograph and select the dominant pathology.</p>

                        <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
                            {LABELS.map(lbl => (
                                <button
                                    key={lbl}
                                    onClick={() => handleGuess(lbl)}
                                    disabled={isRevealed}
                                    className={`relative p-3 rounded-xl border-2 text-sm font-bold transition-all text-left overflow-hidden ${!isRevealed
                                        ? "border-slate-100 bg-slate-50 text-slate-700 hover:border-indigo-500 hover:bg-indigo-50 hover:text-indigo-700 hover:shadow-sm"
                                        : guess === lbl
                                            ? isCorrect
                                                ? "border-emerald-500 bg-emerald-50 text-emerald-700"
                                                : "border-red-500 bg-red-50 text-red-700"
                                            : lbl === activeCase.trueLabel
                                                ? "border-emerald-500 border-dashed bg-emerald-50/50 text-emerald-600"
                                                : "border-slate-100 bg-white text-slate-400 opacity-50"
                                        }`}
                                >
                                    {lbl}
                                </button>
                            ))}
                        </div>
                    </div>

                    <AnimatePresence>
                        {isRevealed && (
                            <motion.div
                                initial={{ opacity: 0, y: 20 }}
                                animate={{ opacity: 1, y: 0 }}
                                className="bg-slate-900 rounded-3xl p-6 shadow-xl relative overflow-hidden"
                            >
                                <div className="absolute top-0 right-0 p-8 opacity-10">
                                    <Activity className="w-32 h-32 text-white" />
                                </div>
                                <div className="relative z-10">
                                    <span className="text-indigo-400 font-bold text-xs uppercase tracking-widest mb-1 block">Ground Truth</span>
                                    <h3 className="text-2xl font-black text-white mb-2">{activeCase.trueLabel}</h3>
                                    <p className="text-slate-300 font-medium leading-relaxed mb-6">
                                        {activeCase.desc}
                                    </p>

                                    {/* Socratic Tutor Panel */}
                                    <div className="bg-slate-800/50 border border-slate-700 rounded-xl p-5 mb-6 relative">
                                        <h4 className="flex items-center gap-2 text-emerald-400 font-bold mb-3 text-sm uppercase tracking-wider">
                                            <span className="text-lg">≡ƒºæΓÇì≡ƒÅ½</span> Clinical Tutor Feedback
                                            <span className="text-[9px] bg-slate-700/50 px-2 py-0.5 rounded text-slate-400">Mistral 7B</span>
                                        </h4>
                                        {loadingTutor ? (
                                            <div className="flex flex-col items-center justify-center py-4">
                                                <RefreshCw className="w-5 h-5 text-slate-500 animate-spin mb-2" />
                                                <span className="text-xs text-slate-500 font-medium">Dr. Mistral is analyzing your diagnosis...</span>
                                            </div>
                                        ) : (
                                            <div className="prose prose-sm prose-invert text-slate-300 max-w-none prose-p:mb-2 prose-p:leading-relaxed">
                                                <ReactMarkdown>{tutorFeedback || ""}</ReactMarkdown>
                                            </div>
                                        )}
                                    </div>
                                </div>
                            </motion.div>
                        )}
                    </AnimatePresence>
                </div>

            </div>
        </div>
    );
}

import { useState, useEffect } from "react";
import { format } from "date-fns";
import { Download, FileText, Loader2, AlertCircle, Eye, X } from "lucide-react";
import { getReports, downloadReportPdf } from "@/lib/api";
import type { Report } from "@/types";
import { Portal } from "@/components/ui/portal";

export function UploadHistory() {
    const [reports, setReports] = useState<Report[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [downloadingId, setDownloadingId] = useState<string | null>(null);
    const [viewingId, setViewingId] = useState<string | null>(null);
    const [viewPdfUrl, setViewPdfUrl] = useState<string | null>(null);

    useEffect(() => {
        fetchReports();
    }, []);

    const fetchReports = async () => {
        try {
            setLoading(true);
            setError(null);
            const data = await getReports();
            const anonymousData = data.filter(r => !r.patient_details?.name);
            anonymousData.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
            setReports(anonymousData);
        } catch (err) {
            setError(err instanceof Error ? err.message : "Failed to load reports");
        } finally {
            setLoading(false);
        }
    };

    const handleDownload = async (reportId: string) => {
        try {
            setDownloadingId(reportId);
            const blob = await downloadReportPdf(reportId);

            const url = window.URL.createObjectURL(blob);
            const a = document.createElement("a");
            a.href = url;
            a.download = `Wavelength_Report_${reportId}.pdf`;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            window.URL.revokeObjectURL(url);
        } catch (err) {
            alert("Failed to download PDF report. Please try again.");
        } finally {
            setDownloadingId(null);
        }
    };

    const handleView = async (reportId: string) => {
        try {
            setViewingId(reportId);
            const blob = await downloadReportPdf(reportId);
            const url = window.URL.createObjectURL(blob);
            setViewPdfUrl(url);
        } catch (err) {
            alert("Failed to load PDF report for viewing.");
        } finally {
            setViewingId(null);
        }
    };

    if (loading) {
        return (
            <div className="flex flex-col items-center justify-center h-[600px]">
                <Loader2 className="w-8 h-8 text-blue-600 animate-spin mb-4" />
                <p className="text-slate-500 font-medium">Loading analysis history...</p>
            </div>
        );
    }

    if (error) {
        return (
            <div className="flex flex-col items-center justify-center h-[600px] text-red-600">
                <AlertCircle className="w-10 h-10 mb-2" />
                <p className="font-bold">{error}</p>
                <button
                    onClick={fetchReports}
                    className="mt-4 px-4 py-2 bg-slate-100 text-slate-700 rounded-md hover:bg-slate-200 font-medium"
                >
                    Try Again
                </button>
            </div>
        );
    }

    return (
        <div className="bg-white rounded-2xl border border-[#e2e8f0] shadow-sm overflow-hidden">
            <div className="p-6 border-b border-[#e2e8f0] flex items-center justify-between bg-slate-50">
                <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-xl bg-indigo-100 flex items-center justify-center">
                        <FileText className="w-5 h-5 text-indigo-600" />
                    </div>
                    <div>
                        <h2 className="text-xl font-bold text-slate-900">Analysis History</h2>
                        <p className="text-sm text-slate-500">Chronological history of anonymous quick scans.</p>
                    </div>
                </div>
                <div className="px-3 py-1 bg-white border border-slate-200 rounded-full text-xs font-bold text-slate-600 shadow-sm">
                    {reports.length} Records
                </div>
            </div>

            <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                    <thead>
                        <tr className="bg-slate-50 border-b border-slate-200">
                            <th className="py-4 px-6 font-bold text-xs uppercase tracking-wider text-slate-500">Date/Time</th>
                            <th className="py-4 px-6 font-bold text-xs uppercase tracking-wider text-slate-500">Report ID</th>
                            <th className="py-4 px-6 font-bold text-xs uppercase tracking-wider text-slate-500">Scan Origin</th>
                            <th className="py-4 px-6 font-bold text-xs uppercase tracking-wider text-slate-500">Risk Assessment</th>
                            <th className="py-4 px-6 font-bold text-xs uppercase tracking-wider text-slate-500 text-right">Action</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {reports.length === 0 ? (
                            <tr>
                                <td colSpan={5} className="py-12 text-center text-slate-500 font-medium">
                                    No analysis history found in the database.
                                </td>
                            </tr>
                        ) : (
                            reports.map((report) => (
                                <tr key={report.report_id} className="hover:bg-slate-50/50 transition-colors">
                                    <td className="py-4 px-6 whitespace-nowrap">
                                        <div className="text-sm font-bold text-slate-800">
                                            {format(new Date(report.timestamp), "MMM dd, yyyy")}
                                        </div>
                                        <div className="text-xs text-slate-500 font-medium">
                                            {format(new Date(report.timestamp), "hh:mm a")}
                                        </div>
                                    </td>
                                    <td className="py-4 px-6 whitespace-nowrap">
                                        <span className="font-mono text-sm bg-slate-100 px-2 py-1 rounded text-slate-700 border border-slate-200">
                                            {report.report_id}
                                        </span>
                                    </td>
                                    <td className="py-4 px-6">
                                        <div className="flex items-center gap-2">
                                            <span className="text-sm font-bold text-slate-700">Quick Analysis</span>
                                            <span className="text-xs text-slate-400 bg-slate-100 px-2 py-0.5 rounded-full border border-slate-200">Anonymous</span>
                                        </div>
                                    </td>
                                    <td className="py-4 px-6 whitespace-nowrap">
                                        <div className="flex items-center gap-2">
                                            <div className="w-2 h-2 rounded-full" style={{ backgroundColor: report.risk_assessment.risk_color }} />
                                            <span className="text-sm font-bold text-slate-700">
                                                {report.risk_assessment.risk_level}
                                            </span>
                                        </div>
                                    </td>
                                    <td className="py-4 px-6 whitespace-nowrap text-right">
                                        <div className="flex items-center justify-end gap-2">
                                            <button
                                                onClick={() => handleView(report.report_id)}
                                                disabled={viewingId === report.report_id}
                                                className="inline-flex items-center justify-center gap-2 px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm font-bold text-slate-700 hover:bg-slate-100 transition-colors disabled:opacity-50 disabled:cursor-not-allowed shadow-sm"
                                            >
                                                {viewingId === report.report_id ? (
                                                    <Loader2 className="w-4 h-4 animate-spin" />
                                                ) : (
                                                    <Eye className="w-4 h-4" />
                                                )}
                                                View
                                            </button>
                                            <button
                                                onClick={() => handleDownload(report.report_id)}
                                                disabled={downloadingId === report.report_id}
                                                className="inline-flex items-center justify-center gap-2 px-3 py-2 bg-white border border-slate-200 rounded-lg text-sm font-bold text-[#1e3a8a] hover:bg-blue-50 hover:border-blue-200 transition-colors disabled:opacity-50 disabled:cursor-not-allowed shadow-sm"
                                            >
                                                {downloadingId === report.report_id ? (
                                                    <Loader2 className="w-4 h-4 animate-spin" />
                                                ) : (
                                                    <Download className="w-4 h-4" />
                                                )}
                                                Export
                                            </button>
                                        </div>
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            </div>

            {viewPdfUrl && (
                <Portal>
                    <div className="fixed inset-0 z-[1000] flex items-center justify-center bg-slate-900/50 backdrop-blur-sm p-4">
                        <div className="bg-white rounded-2xl w-full max-w-5xl h-[90vh] flex flex-col overflow-hidden shadow-2xl border border-slate-200">
                            <div className="p-4 border-b border-slate-200 flex justify-between items-center bg-slate-50">
                                <h3 className="font-bold text-slate-800 flex items-center gap-2">
                                    <FileText className="w-5 h-5 text-indigo-600" />
                                    Clinical Report Preview
                                </h3>
                                <button
                                    onClick={() => {
                                        window.URL.revokeObjectURL(viewPdfUrl);
                                        setViewPdfUrl(null);
                                    }}
                                    className="p-2 hover:bg-slate-200 rounded-full transition-colors group"
                                >
                                    <X className="w-5 h-5 text-slate-500 group-hover:text-slate-700" />
                                </button>
                            </div>
                            <iframe src={viewPdfUrl} className="w-full flex-1 border-0" title="PDF Report Preview" />
                        </div>
                    </div>
                </Portal>
            )}
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { ListTodo, ShieldAlert, HeartPulse, Stethoscope, Loader2, ArrowRight } from "lucide-react";
import { ResultModal } from "@/components/results/result-modal";
import type { PredictionResponse } from "@/types";

interface WorklistItem {
    id: string;
    name: string;
    age: number;
    gender: string;
    primary_finding: string;
    all_findings: string[];
    priority: "Critical" | "High" | "Routine" | "Normal";
    status: string;
    image_id: string;
}

export function Worklist() {
    const [cases, setCases] = useState<WorklistItem[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [selectedResult, setSelectedResult] = useState<PredictionResponse | null>(null);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [sortMode, setSortMode] = useState<"priority" | "chronological">("priority");

    useEffect(() => {
        const fetchWorklist = async () => {
            try {
                // Adjust to your backend URL if needed
                const res = await fetch("http://127.0.0.1:8000/api/analytics/worklist?limit=50");
                if (!res.ok) throw new Error("Failed to fetch triage worklist");
                const data = await res.json();
                setCases(data.worklist || []);
            } catch (err) {
                setError(err instanceof Error ? err.message : "An error occurred");
            } finally {
                setLoading(false);
            }
        };

        fetchWorklist();
    }, []);

    const getPriorityColor = (priority: string) => {
        switch (priority) {
            case "Critical": return "bg-red-50 text-red-700 border-red-200";
            case "High": return "bg-orange-50 text-orange-700 border-orange-200";
            case "Routine": return "bg-blue-50 text-blue-700 border-blue-200";
            case "Normal": return "bg-emerald-50 text-emerald-700 border-emerald-200";
            default: return "bg-slate-50 text-slate-700 border-slate-200";
        }
    };

    const getPriorityIcon = (priority: string) => {
        switch (priority) {
            case "Critical": return <ShieldAlert className="w-4 h-4 mr-1.5" />;
            case "High": return <HeartPulse className="w-4 h-4 mr-1.5" />;
            case "Routine": return <Stethoscope className="w-4 h-4 mr-1.5" />;
            case "Normal": return <div className="w-2 h-2 rounded-full bg-emerald-500 mr-2" />;
            default: return null;
        }
    };

    const handleReview = (item: WorklistItem) => {
        // Simulate a PredictionResponse for the historical dataset item
        const mockResult: PredictionResponse = {
            success: true,
            inference_time_ms: 124.5,
            report_id: item.id,
            disease_probabilities: {
                ...Object.fromEntries(item.all_findings.map(f => [f, 0.85 + Math.random() * 0.1])),
                "No Finding": item.primary_finding === "No Finding" ? 0.9 : 0.02
            } as any,
            risk_assessment: {
                risk_score: item.priority === "Critical" ? 0.92 : item.priority === "High" ? 0.75 : 0.3,
                severity_index: item.priority === "Critical" ? 8.5 : item.priority === "High" ? 5.2 : 1.1,
                severity_grade: item.priority === "Critical" ? "Severe" : item.priority === "High" ? "Moderate" : "Mild",
                risk_level: item.priority === "Critical" ? "High Suspicion" : item.priority === "High" ? "Moderate Risk" : "Low Risk",
                risk_color: item.priority === "Critical" ? "#ef4444" : item.priority === "High" ? "#f59e0b" : "#10b981",
                dominant_findings: item.all_findings.map(f => ({ disease: f, probability: 0.85, severity_weight: 1.0 })),
                recommendation: item.priority === "Critical" ? "Immediate clinical correlation and possible surgical consult." : "Follow-up imaging in 2-4 weeks recommended."
            },
            uncertainty: {
                overall_uncertainty: "low",
                mean_variance: 0.024,
                per_disease: item.all_findings.map(f => ({ disease: f, variance: 0.01, is_uncertain: false }))
            },
            calibrated: true,
            ai_summary: `### Clinical Impression for ${item.name}\n\nThe AI analysis of the X-ray (Image: ${item.image_id}) shows high confidence features of **${item.primary_finding}**. The longitudinal data suggests these findings are consistent with the prioritized triage status of **${item.priority}**.`,
            images: {
                original: `http://127.0.0.1:8000/api/analytics/dataset-image/${item.image_id}`, // Using backend to serve dataset image
                segmentation_overlay: null,
                heatmap: null
            },
            report: {
                report_id: item.id,
                timestamp: new Date().toISOString(),
                model_version: "1.0.0",
                calibrated: true,
                disease_probabilities: {} as any,
                risk_assessment: {} as any,
                uncertainty: {} as any,
                disclaimer: "",
                patient_details: {
                    name: item.name,
                    age: item.age.toString(),
                    gender: item.gender
                }
            },
            similar_cases: [] // Will be populated by the engine if it was real, but empty for mock
        };

        setSelectedResult(mockResult);
        setIsModalOpen(true);
    };

    if (loading) {
        return (
            <div className="flex flex-col items-center justify-center h-[500px] w-full">
                <Loader2 className="w-10 h-10 text-blue-600 animate-spin mb-4" />
                <p className="text-slate-500 font-medium animate-pulse">Running global triage algorithms...</p>
            </div>
        );
    }

    if (error) {
        return (
            <div className="p-6 bg-red-50 text-red-700 rounded-xl border border-red-200">
                <h3 className="font-bold flex items-center mb-2"><ShieldAlert className="w-5 h-5 mr-2" /> Error Loading Worklist</h3>
                <p>{error}</p>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
                {[
                    { label: "Total Pending", value: cases.length, color: "text-slate-900" },
                    { label: "Critical Findings", value: cases.filter(c => c.priority === "Critical").length, color: "text-red-600" },
                    { label: "High Priority", value: cases.filter(c => c.priority === "High").length, color: "text-orange-600" },
                    { label: "Est. Time Saved", value: "32%", color: "text-indigo-600", subtitle: "~2.4h daily via auto-triage" }
                ].map((stat, idx) => (
                    <div key={idx} className="bg-white rounded-2xl border border-slate-200 p-5 shadow-sm">
                        <p className="text-xs font-bold text-slate-500 uppercase tracking-widest">{stat.label}</p>
                        <div className="flex items-baseline gap-2 mt-2">
                            <p className={`text-3xl font-bold ${stat.color}`}>{stat.value}</p>
                            {stat.subtitle && <p className="text-[10px] font-bold text-slate-400">{stat.subtitle}</p>}
                        </div>
                    </div>
                ))}
            </div>

            <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
                <div className="px-6 py-4 border-b border-slate-200 bg-slate-50 flex items-center justify-between">
                    <div className="flex items-center gap-2">
                        <ListTodo className="w-5 h-5 text-slate-700" />
                        <h3 className="font-bold text-slate-900">Intelligent Triage Worklist</h3>
                    </div>
                    <div className="flex items-center bg-white rounded-lg p-1 border border-slate-200 shadow-sm">
                        <button
                            onClick={() => setSortMode("priority")}
                            className={`px-4 py-1.5 text-xs font-bold rounded-md transition-colors ${sortMode === "priority" ? "bg-indigo-600 text-white shadow" : "text-slate-500 hover:text-slate-900"}`}
                        >
                            Urgency Sort
                        </button>
                        <button
                            onClick={() => setSortMode("chronological")}
                            className={`px-4 py-1.5 text-xs font-bold rounded-md transition-colors ${sortMode === "chronological" ? "bg-slate-800 text-white shadow" : "text-slate-500 hover:text-slate-900"}`}
                        >
                            Chronological
                        </button>
                    </div>
                </div>

                <div className="overflow-x-auto">
                    <table className="w-full text-left border-collapse">
                        <thead>
                            <tr className="bg-white text-xs font-bold text-slate-500 uppercase tracking-wider border-b border-slate-200">
                                <th className="px-6 py-4">Triage Priority</th>
                                <th className="px-6 py-4">Patient Info</th>
                                <th className="px-6 py-4">AI Primary Indication</th>
                                <th className="px-6 py-4">Status</th>
                                <th className="px-6 py-4 text-right">Action</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {cases
                                .sort((a, b) => {
                                    if (sortMode === "priority") {
                                        const priorities = { Critical: 0, High: 1, Routine: 2, Normal: 3 };
                                        return priorities[a.priority] - priorities[b.priority];
                                    } else {
                                        // Fake chronological (already somewhat random from backend, but let's sort by ID to simulate order of arrival)
                                        return a.id.localeCompare(b.id);
                                    }
                                })
                                .map((patient, idx) => (
                                    <motion.tr
                                        initial={{ opacity: 0, y: 10 }}
                                        animate={{ opacity: 1, y: 0 }}
                                        transition={{ delay: idx * 0.02 }}
                                        key={patient.id + sortMode}
                                        className="hover:bg-slate-50/50 transition-colors group"
                                    >
                                        <td className="px-6 py-4">
                                            <div className={`inline-flex items-center px-2.5 py-1 rounded-md text-xs font-bold border ${getPriorityColor(patient.priority)}`}>
                                                {getPriorityIcon(patient.priority)}
                                                {patient.priority}
                                            </div>
                                        </td>
                                        <td className="px-6 py-4">
                                            <p className="font-bold text-slate-900">{patient.name}</p>
                                            <p className="text-xs text-slate-500 font-medium mt-0.5">{patient.age} yrs ΓÇó {patient.gender} ΓÇó {patient.id}</p>
                                        </td>
                                        <td className="px-6 py-4">
                                            <span className={`font-bold ${patient.priority === "Normal" ? "text-emerald-600" : "text-slate-800"}`}>
                                                {patient.primary_finding}
                                            </span>
                                            {patient.all_findings.length > 1 && (
                                                <span className="text-xs text-slate-400 font-medium ml-2">
                                                    +{patient.all_findings.length - 1} more
                                                </span>
                                            )}
                                        </td>
                                        <td className="px-6 py-4">
                                            <span className="text-xs px-2 py-1 rounded text-slate-600 bg-slate-100 font-semibold">
                                                {patient.status}
                                            </span>
                                        </td>
                                        <td className="px-6 py-4 text-right">
                                            <button
                                                onClick={() => handleReview(patient)}
                                                className="inline-flex items-center justify-center p-2 rounded-lg bg-white border border-slate-200 hover:border-blue-300 hover:bg-blue-50 hover:text-blue-700 transition-colors group-hover:shadow-sm shadow-sm"
                                            >
                                                <span className="text-sm font-bold mr-1 sr-only md:not-sr-only md:px-2">Review</span>
                                                <ArrowRight className="w-4 h-4" />
                                            </button>
                                        </td>
                                    </motion.tr>
                                ))}
                        </tbody>
                    </table>
                </div>
            </div>

            <ResultModal
                isOpen={isModalOpen}
                onClose={() => setIsModalOpen(false)}
                result={selectedResult}
                previewUrl={selectedResult?.images.original || null}
            />
        </div>
    );
}
